-- ==== 0011_fixes.sql ====
-- 0011 Fixes found while testing against a live project. Safe to run more than once.

-- Bill allocations sent as JSON null (rather than left out) meant "settle oldest first",
-- but jsonb_array_length failed on the null. Treat anything that isn't an array as "none".
create or replace function public.settle_bills(p_id uuid, p_allocations jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare
  t public.money_txns;
  v_left numeric;
  v_take numeric;
  a jsonb;
  r record;
begin
  select * into t from public.money_txns where id = p_id;
  delete from public.bill_settlements where money_txn_id = p_id;
  if t.txn_type not in ('RECEIPT', 'PAYMENT') or t.cheque_status = 'BOUNCED' then
    return;
  end if;
  v_left := t.amount;

  if jsonb_typeof(p_allocations) = 'array' and jsonb_array_length(p_allocations) > 0 then
    for a in select * from jsonb_array_elements(p_allocations) loop
      v_take := least(coalesce(nullif(a->>'amount', '')::numeric, 0), v_left);
      continue when v_take <= 0;
      insert into public.bill_settlements (money_txn_id, sale_id, purchase_id, amount)
      values (p_id, nullif(a->>'sale_id', '')::uuid, nullif(a->>'purchase_id', '')::uuid, v_take);
      v_left := v_left - v_take;
    end loop;
    return;
  end if;

  if t.txn_type = 'RECEIPT' then
    for r in select id, due_amount from public.v_sale_dues
             where customer_id = t.party_id and due_amount > 0.005 order by sale_date, sale_no loop
      exit when v_left <= 0.005;
      v_take := least(r.due_amount, v_left);
      insert into public.bill_settlements (money_txn_id, sale_id, amount) values (p_id, r.id, v_take);
      v_left := v_left - v_take;
    end loop;
  else
    for r in select id, due_amount from public.v_purchase_dues
             where supplier_id = t.party_id and due_amount > 0.005 order by purchase_date, purchase_no loop
      exit when v_left <= 0.005;
      v_take := least(r.due_amount, v_left);
      insert into public.bill_settlements (money_txn_id, purchase_id, amount) values (p_id, r.id, v_take);
      v_left := v_left - v_take;
    end loop;
  end if;
end;
$$;

revoke execute on function public.settle_bills(uuid, jsonb) from public, anon, authenticated;


-- ==== 0012_business_rules.sql ====
-- 0012 Business rule improvements
--
-- 1. A per-bag rate needs a bag count.
-- 3. Each sale line can ship from its own godown.
-- 4. Money received at a sale / paid at a purchase becomes a linked receipt / payment voucher,
--    so it can be cash, bank or a cheque that later clears or bounces. Existing records are converted.
-- 5. An invoice or bill cannot be lowered below what has already been paid against it.
-- 6. Loan repayments and recoveries can include interest.
-- 7. Dues ageing works on each party's whole balance (oldest-first), not only on bills.
--
-- Safe to run on a project that already has data. Run once.

------------------------------------------------------------------------------------------
-- Schema
------------------------------------------------------------------------------------------
alter table public.sale_lines add column if not exists warehouse_id uuid references public.warehouses(id);

alter table public.sales add column if not exists received_method text not null default 'CASH'
  check (received_method in ('CASH', 'BANK', 'CHEQUE'));
alter table public.sales add column if not exists received_cheque_no text;
alter table public.sales add column if not exists received_cheque_date date;

alter table public.purchases add column if not exists paid_method text not null default 'CASH'
  check (paid_method in ('CASH', 'BANK', 'CHEQUE'));
alter table public.purchases add column if not exists paid_cheque_no text;
alter table public.purchases add column if not exists paid_cheque_date date;

alter table public.money_txns add column if not exists linked_sale_id uuid references public.sales(id) on delete cascade;
alter table public.money_txns add column if not exists linked_purchase_id uuid references public.purchases(id) on delete cascade;
alter table public.money_txns add column if not exists interest_amount numeric(14,2) not null default 0
  check (interest_amount >= 0);

create index if not exists money_txns_linked_sale_idx on public.money_txns (linked_sale_id) where linked_sale_id is not null;
create index if not exists money_txns_linked_purchase_idx on public.money_txns (linked_purchase_id) where linked_purchase_id is not null;

insert into public.accounts (code, name, name_bn, type, subtype, is_system) values
  ('4110', 'Interest Received', 'প্রাপ্ত সুদ', 'INCOME', 'INTEREST_INCOME', true),
  ('6095', 'Loan Interest', 'ঋণের সুদ', 'EXPENSE', 'INTEREST_EXPENSE', true)
on conflict (code) do nothing;

------------------------------------------------------------------------------------------
-- Dues: paid = settlements (every receipt/payment, including those made at the sale/purchase) + returns
------------------------------------------------------------------------------------------
drop view if exists public.v_sale_dues;
create view public.v_sale_dues with (security_invoker = true) as
select
  s.*, p.name as customer_name, p.name_bn as customer_name_bn,
  coalesce(st.settled, 0) + coalesce(rt.returned, 0) as total_paid,
  s.total_amount - coalesce(st.settled, 0) - coalesce(rt.returned, 0) as due_amount,
  current_date - s.sale_date as age_days
from public.sales s
join public.parties p on p.id = s.customer_id
left join (select sale_id, sum(amount) as settled from public.bill_settlements where sale_id is not null group by sale_id) st on st.sale_id = s.id
left join (select sale_id, sum(amount) as returned from public.sale_returns where sale_id is not null group by sale_id) rt on rt.sale_id = s.id;

drop view if exists public.v_purchase_dues;
create view public.v_purchase_dues with (security_invoker = true) as
select
  pu.*, p.name as supplier_name, p.name_bn as supplier_name_bn, pu.supplier_total as total_amount,
  coalesce(st.settled, 0) + coalesce(rt.returned, 0) as total_paid,
  pu.supplier_total - coalesce(st.settled, 0) - coalesce(rt.returned, 0) as due_amount,
  current_date - pu.purchase_date as age_days
from public.purchases pu
join public.parties p on p.id = pu.supplier_id
left join (select purchase_id, sum(amount) as settled from public.bill_settlements where purchase_id is not null group by purchase_id) st on st.purchase_id = pu.id
left join (select purchase_id, sum(amount) as returned from public.purchase_returns where purchase_id is not null group by purchase_id) rt on rt.purchase_id = pu.id;

drop view if exists public.v_money_txns;
create view public.v_money_txns with (security_invoker = true) as
select
  t.*,
  m.name as money_account_name, m.subtype as money_account_subtype,
  c.name as counter_account_name,
  p.name as party_name,
  s.sale_no as linked_sale_no,
  pu.purchase_no as linked_purchase_no
from public.money_txns t
join public.accounts m on m.id = t.money_account_id
left join public.accounts c on c.id = t.counter_account_id
left join public.parties p on p.id = t.party_id
left join public.sales s on s.id = t.linked_sale_id
left join public.purchases pu on pu.id = t.linked_purchase_id;

------------------------------------------------------------------------------------------
-- Money
------------------------------------------------------------------------------------------
create or replace function public.post_money_txn(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  t public.money_txns;
  v_lines jsonb;
  v_label text;
  v_principal numeric;
begin
  select * into t from public.money_txns where id = p_id;
  if t.cheque_status = 'BOUNCED' then
    return;
  end if;

  if t.txn_type in ('RECEIPT', 'PAYMENT', 'LOAN_TAKEN', 'LOAN_REPAY', 'LOAN_GIVEN', 'LOAN_RECOVER') and t.party_id is null then
    raise exception 'Choose the party';
  end if;
  if t.txn_type in ('EXPENSE', 'INCOME', 'TRANSFER') and t.counter_account_id is null then
    raise exception 'Choose the account';
  end if;
  v_principal := t.amount - t.interest_amount;

  v_lines := case t.txn_type
    when 'RECEIPT' then jsonb_build_array(
      public.jl_dr(t.money_account_id, t.amount), public.jl_cr(public.system_account('RECEIVABLE'), t.amount, t.party_id))
    when 'PAYMENT' then jsonb_build_array(
      public.jl_dr(public.system_account('PAYABLE'), t.amount, t.party_id), public.jl_cr(t.money_account_id, t.amount))
    when 'EXPENSE' then jsonb_build_array(
      public.jl_dr(t.counter_account_id, t.amount), public.jl_cr(t.money_account_id, t.amount))
    when 'INCOME' then jsonb_build_array(
      public.jl_dr(t.money_account_id, t.amount), public.jl_cr(t.counter_account_id, t.amount))
    when 'TRANSFER' then jsonb_build_array(
      public.jl_dr(t.counter_account_id, t.amount), public.jl_cr(t.money_account_id, t.amount))
    when 'CAPITAL_IN' then jsonb_build_array(
      public.jl_dr(t.money_account_id, t.amount), public.jl_cr(public.system_account('CAPITAL'), t.amount))
    when 'DRAWING' then jsonb_build_array(
      public.jl_dr(public.system_account('DRAWINGS'), t.amount), public.jl_cr(t.money_account_id, t.amount))
    when 'LOAN_TAKEN' then jsonb_build_array(
      public.jl_dr(t.money_account_id, t.amount), public.jl_cr(public.system_account('LOAN_PAYABLE'), t.amount, t.party_id))
    when 'LOAN_REPAY' then jsonb_build_array(
      public.jl_dr(public.system_account('LOAN_PAYABLE'), v_principal, t.party_id),
      public.jl_dr(public.system_account('INTEREST_EXPENSE'), t.interest_amount, null, 'Interest'),
      public.jl_cr(t.money_account_id, t.amount))
    when 'LOAN_GIVEN' then jsonb_build_array(
      public.jl_dr(public.system_account('LOAN_RECEIVABLE'), t.amount, t.party_id), public.jl_cr(t.money_account_id, t.amount))
    when 'LOAN_RECOVER' then jsonb_build_array(
      public.jl_dr(t.money_account_id, t.amount),
      public.jl_cr(public.system_account('LOAN_RECEIVABLE'), v_principal, t.party_id),
      public.jl_cr(public.system_account('INTEREST_INCOME'), t.interest_amount, null, 'Interest'))
  end;

  v_label := initcap(replace(lower(t.txn_type), '_', ' ')) || ' ' || t.txn_no;
  perform public.post_journal(t.txn_date, 'MONEY', t.id, coalesce(nullif(t.notes, ''), v_label), v_lines);
end;
$$;

create or replace function public.settle_bills(p_id uuid, p_allocations jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare
  t public.money_txns;
  v_left numeric;
  v_take numeric;
  a jsonb;
  r record;
begin
  select * into t from public.money_txns where id = p_id;
  delete from public.bill_settlements where money_txn_id = p_id;
  if t.txn_type not in ('RECEIPT', 'PAYMENT') or t.cheque_status = 'BOUNCED' then
    return;
  end if;

  -- money taken at a sale or purchase always settles that document
  if t.linked_sale_id is not null then
    insert into public.bill_settlements (money_txn_id, sale_id, amount) values (p_id, t.linked_sale_id, t.amount);
    return;
  end if;
  if t.linked_purchase_id is not null then
    insert into public.bill_settlements (money_txn_id, purchase_id, amount) values (p_id, t.linked_purchase_id, t.amount);
    return;
  end if;

  v_left := t.amount;
  if jsonb_typeof(p_allocations) = 'array' and jsonb_array_length(p_allocations) > 0 then
    for a in select * from jsonb_array_elements(p_allocations) loop
      v_take := least(coalesce(nullif(a->>'amount', '')::numeric, 0), v_left);
      continue when v_take <= 0;
      insert into public.bill_settlements (money_txn_id, sale_id, purchase_id, amount)
      values (p_id, nullif(a->>'sale_id', '')::uuid, nullif(a->>'purchase_id', '')::uuid, v_take);
      v_left := v_left - v_take;
    end loop;
    return;
  end if;

  if t.txn_type = 'RECEIPT' then
    for r in select id, due_amount from public.v_sale_dues
             where customer_id = t.party_id and due_amount > 0.005 order by sale_date, sale_no loop
      exit when v_left <= 0.005;
      v_take := least(r.due_amount, v_left);
      insert into public.bill_settlements (money_txn_id, sale_id, amount) values (p_id, r.id, v_take);
      v_left := v_left - v_take;
    end loop;
  else
    for r in select id, due_amount from public.v_purchase_dues
             where supplier_id = t.party_id and due_amount > 0.005 order by purchase_date, purchase_no loop
      exit when v_left <= 0.005;
      v_take := least(r.due_amount, v_left);
      insert into public.bill_settlements (money_txn_id, purchase_id, amount) values (p_id, r.id, v_take);
      v_left := v_left - v_take;
    end loop;
  end if;
end;
$$;

-- Receipt / payment made together with a sale or purchase
create or replace function public.create_linked_money_txn(
  p_type text, p_date date, p_party uuid, p_account uuid, p_amount numeric,
  p_method text, p_cheque_no text, p_cheque_date date, p_sale uuid, p_purchase uuid, p_note text
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid;
begin
  if p_account is null then
    raise exception 'Choose the cash or bank account';
  end if;
  insert into public.money_txns (txn_no, txn_date, txn_type, party_id, money_account_id, amount, method,
    cheque_no, cheque_date, cheque_status, notes, linked_sale_id, linked_purchase_id)
  values (public.next_doc_no(case p_type when 'RECEIPT' then 'RCV' else 'PAY' end, p_date), p_date, p_type, p_party,
    p_account, p_amount, coalesce(p_method, 'CASH'), p_cheque_no, p_cheque_date,
    case when p_method = 'CHEQUE' then 'PENDING' end, p_note, p_sale, p_purchase)
  returning id into v_id;
  perform public.post_money_txn(v_id);
  perform public.settle_bills(v_id, null);
  return v_id;
end;
$$;

create or replace function public.remove_linked_money_txns(p_sale uuid, p_purchase uuid)
returns void language plpgsql security definer set search_path = public as $$
declare r record;
begin
  for r in select id from public.money_txns
           where (p_sale is not null and linked_sale_id = p_sale) or (p_purchase is not null and linked_purchase_id = p_purchase) loop
    perform public.unpost_journal('MONEY', r.id);
    delete from public.money_txns where id = r.id;
  end loop;
end;
$$;

create or replace function public.save_money_txn(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_date date := (p->>'txn_date')::date;
  v_type text := p->>'txn_type';
  v_no text;
  v_method text := coalesce(nullif(p->>'method', ''), 'CASH');
  v_amount numeric := nullif(p->>'amount', '')::numeric;
  v_interest numeric := coalesce(nullif(p->>'interest_amount', '')::numeric, 0);
  v_link text;
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT');

  if v_id is not null then
    select coalesce(s.sale_no, pu.purchase_no) into v_link
    from public.money_txns t
    left join public.sales s on s.id = t.linked_sale_id
    left join public.purchases pu on pu.id = t.linked_purchase_id
    where t.id = v_id and (t.linked_sale_id is not null or t.linked_purchase_id is not null);
    if v_link is not null then
      raise exception 'This was recorded with % — change it there', v_link;
    end if;
    perform public.unpost_journal('MONEY', v_id);
    select txn_no into v_no from public.money_txns where id = v_id;
  else
    v_id := gen_random_uuid();
    v_no := public.next_doc_no(case v_type
      when 'RECEIPT' then 'RCV' when 'PAYMENT' then 'PAY' when 'EXPENSE' then 'EXP' when 'INCOME' then 'INC'
      when 'TRANSFER' then 'TRN' when 'CAPITAL_IN' then 'CAP' when 'DRAWING' then 'DRW' else 'LON' end, v_date);
  end if;

  if v_type = 'TRANSFER' and p->>'counter_account_id' = p->>'money_account_id' then
    raise exception 'Choose two different accounts for a transfer';
  end if;
  if v_type not in ('LOAN_REPAY', 'LOAN_RECOVER') then
    v_interest := 0;
  elsif v_interest > coalesce(v_amount, 0) then
    raise exception 'Interest cannot be more than the amount';
  end if;

  insert into public.money_txns (id, txn_no, txn_date, txn_type, party_id, money_account_id, counter_account_id, amount,
    interest_amount, method, cheque_no, cheque_date, cheque_status, reference, notes)
  values (v_id, v_no, v_date, v_type, nullif(p->>'party_id', '')::uuid, (p->>'money_account_id')::uuid,
    nullif(p->>'counter_account_id', '')::uuid, v_amount, v_interest, v_method,
    p->>'cheque_no', nullif(p->>'cheque_date', '')::date,
    case when v_method = 'CHEQUE' then coalesce(nullif(p->>'cheque_status', ''), 'PENDING') end,
    p->>'reference', p->>'notes')
  on conflict (id) do update set
    txn_date = excluded.txn_date, txn_type = excluded.txn_type, party_id = excluded.party_id,
    money_account_id = excluded.money_account_id, counter_account_id = excluded.counter_account_id,
    amount = excluded.amount, interest_amount = excluded.interest_amount, method = excluded.method,
    cheque_no = excluded.cheque_no, cheque_date = excluded.cheque_date, cheque_status = excluded.cheque_status,
    reference = excluded.reference, notes = excluded.notes, updated_at = now();

  perform public.post_money_txn(v_id);
  perform public.settle_bills(v_id, p->'allocations');
  return v_id;
end;
$$;

create or replace function public.delete_money_txn(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT');
  if exists (select 1 from public.money_txns where id = p_id and (linked_sale_id is not null or linked_purchase_id is not null)) then
    raise exception 'This was recorded with a sale or purchase — change it there';
  end if;
  perform public.unpost_journal('MONEY', p_id);
  delete from public.money_txns where id = p_id;
end;
$$;

------------------------------------------------------------------------------------------
-- Purchases
------------------------------------------------------------------------------------------
create or replace function public.post_purchase_journal(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  h public.purchases;
  v_ap uuid := public.system_account('PAYABLE');
  v_extra numeric;
  v_lines jsonb;
begin
  select * into h from public.purchases where id = p_id;
  v_extra := h.transport_cost + h.labour_cost + h.other_cost;
  v_lines := jsonb_build_array(
    public.jl_dr(public.system_account('INVENTORY'), h.total_cost, null, 'Goods received'),
    public.jl_cr(v_ap, h.goods_amount - h.discount, h.supplier_id, 'Supplier bill')
  );
  if h.commission_amount > 0 then
    if h.broker_id is null then
      raise exception 'Choose the broker to pay commission to';
    end if;
    v_lines := v_lines || public.jl_cr(v_ap, h.commission_amount, h.broker_id, 'Broker commission');
  end if;
  if v_extra > 0 then
    v_lines := v_lines || case when h.costs_account_id is not null
      then public.jl_cr(h.costs_account_id, v_extra, null, 'Transport and labour')
      else public.jl_cr(v_ap, v_extra, h.supplier_id, 'Transport and labour') end;
  end if;
  perform public.post_journal(h.purchase_date, 'PURCHASE', h.id, 'Purchase ' || h.purchase_no, v_lines);
end;
$$;

create or replace function public.post_purchase(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  h public.purchases;
  r public.purchase_lines;
  v_extra numeric;
  v_lot uuid;
  v_unit numeric;
begin
  select * into h from public.purchases where id = p_id;
  v_extra := h.transport_cost + h.labour_cost + h.other_cost + h.commission_amount;

  -- stock: spread extra costs and discount across lines by value
  for r in select * from public.purchase_lines where purchase_id = p_id order by line_no loop
    v_unit := case when r.net_kg > 0 then
      (r.amount + case when h.goods_amount > 0 then v_extra * r.amount / h.goods_amount else 0 end
                - case when h.goods_amount > 0 then h.discount * r.amount / h.goods_amount else 0 end) / r.net_kg
      else 0 end;
    v_lot := public.receive_stock(h.purchase_date, r.item_id, h.warehouse_id, r.net_kg, r.bags, r.bag_size_kg,
      v_unit, 'PURCHASE', h.id, r.id, null, h.purchase_no);
    update public.purchase_lines set lot_id = v_lot, unit_cost = round(v_unit, 6) where id = r.id;
  end loop;

  perform public.post_purchase_journal(p_id);

  if h.paid_amount > 0 then
    perform public.create_linked_money_txn('PAYMENT', h.purchase_date, h.supplier_id, h.paid_account_id, h.paid_amount,
      h.paid_method, h.paid_cheque_no, h.paid_cheque_date, null, h.id, 'Paid with ' || h.purchase_no);
  end if;
end;
$$;

create or replace function public.unpost_purchase(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.remove_linked_money_txns(null, p_id);
  perform public.unpost_stock('PURCHASE', p_id);
  perform public.unpost_journal('PURCHASE', p_id);
end;
$$;

create or replace function public.save_purchase(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_date date := (p->>'purchase_date')::date;
  v_no text := nullif(p->>'purchase_no', '');
  l jsonb;
  v_i int := 0;
  v_goods numeric := 0;
  v_net numeric;
  v_amount numeric;
  v_other_paid numeric;
  h public.purchases;
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT', 'OPERATOR');
  if jsonb_array_length(coalesce(p->'lines', '[]'::jsonb)) = 0 then
    raise exception 'Add at least one item';
  end if;

  if v_id is not null then
    perform public.unpost_purchase(v_id);
    delete from public.purchase_lines where purchase_id = v_id;
    select purchase_no into v_no from public.purchases where id = v_id;
  else
    v_id := gen_random_uuid();
  end if;

  insert into public.purchases (id, purchase_no, purchase_date, supplier_id, broker_id, warehouse_id, vehicle_no, reference, notes,
    discount, transport_cost, labour_cost, other_cost, costs_account_id, commission_amount, paid_amount, paid_account_id,
    paid_method, paid_cheque_no, paid_cheque_date)
  values (v_id, coalesce(v_no, public.next_doc_no('PUR', v_date)), v_date, (p->>'supplier_id')::uuid,
    nullif(p->>'broker_id', '')::uuid, (p->>'warehouse_id')::uuid, p->>'vehicle_no', p->>'reference', p->>'notes',
    coalesce(nullif(p->>'discount', '')::numeric, 0), coalesce(nullif(p->>'transport_cost', '')::numeric, 0),
    coalesce(nullif(p->>'labour_cost', '')::numeric, 0), coalesce(nullif(p->>'other_cost', '')::numeric, 0),
    nullif(p->>'costs_account_id', '')::uuid, coalesce(nullif(p->>'commission_amount', '')::numeric, 0),
    coalesce(nullif(p->>'paid_amount', '')::numeric, 0), nullif(p->>'paid_account_id', '')::uuid,
    coalesce(nullif(p->>'paid_method', ''), 'CASH'), nullif(p->>'paid_cheque_no', ''), nullif(p->>'paid_cheque_date', '')::date)
  on conflict (id) do update set
    purchase_date = excluded.purchase_date, supplier_id = excluded.supplier_id, broker_id = excluded.broker_id,
    warehouse_id = excluded.warehouse_id, vehicle_no = excluded.vehicle_no, reference = excluded.reference,
    notes = excluded.notes, discount = excluded.discount, transport_cost = excluded.transport_cost,
    labour_cost = excluded.labour_cost, other_cost = excluded.other_cost, costs_account_id = excluded.costs_account_id,
    commission_amount = excluded.commission_amount, paid_amount = excluded.paid_amount,
    paid_account_id = excluded.paid_account_id, paid_method = excluded.paid_method,
    paid_cheque_no = excluded.paid_cheque_no, paid_cheque_date = excluded.paid_cheque_date, updated_at = now();

  for l in select * from jsonb_array_elements(p->'lines') loop
    v_i := v_i + 1;
    v_net := coalesce(nullif(l->>'gross_kg', '')::numeric, 0) - coalesce(nullif(l->>'deduction_kg', '')::numeric, 0);
    if v_net <= 0 then
      raise exception 'Line %: net weight must be greater than zero', v_i;
    end if;
    if coalesce(l->>'rate_unit', 'KG') = 'BAG' and coalesce(nullif(l->>'bags', '')::numeric, 0) <= 0 then
      raise exception 'Line %: enter the number of bags for a per-bag rate', v_i;
    end if;
    v_amount := public.line_amount(coalesce(l->>'rate_unit', 'KG'), nullif(l->>'rate', '')::numeric, v_net, nullif(l->>'bags', '')::numeric);
    insert into public.purchase_lines (purchase_id, line_no, item_id, bags, bag_size_kg, gross_kg, deduction_kg, net_kg,
      rate, rate_unit, amount)
    values (v_id, v_i, (l->>'item_id')::uuid, coalesce(nullif(l->>'bags', '')::numeric, 0), coalesce(nullif(l->>'bag_size_kg', '')::numeric, 0),
      nullif(l->>'gross_kg', '')::numeric, coalesce(nullif(l->>'deduction_kg', '')::numeric, 0), v_net,
      coalesce(nullif(l->>'rate', '')::numeric, 0), coalesce(l->>'rate_unit', 'KG'), v_amount);
    v_goods := v_goods + v_amount;
  end loop;

  update public.purchases set
    goods_amount = v_goods,
    supplier_total = v_goods - discount
      + case when costs_account_id is null then transport_cost + labour_cost + other_cost else 0 end,
    total_cost = v_goods - discount + transport_cost + labour_cost + other_cost + commission_amount
  where id = v_id
  returning * into h;

  if h.paid_amount > 0 and h.paid_account_id is null then
    raise exception 'Choose the cash or bank account the payment was made from';
  end if;
  -- already paid by separate payments or returns: the bill can't drop below that
  select coalesce((select sum(bs.amount) from public.bill_settlements bs join public.money_txns m on m.id = bs.money_txn_id
                   where bs.purchase_id = v_id and m.linked_purchase_id is distinct from v_id), 0)
       + coalesce((select sum(amount) from public.purchase_returns where purchase_id = v_id), 0)
  into v_other_paid;
  if h.supplier_total + 0.005 < v_other_paid + h.paid_amount then
    raise exception 'The supplier bill (%) is less than what has already been paid or returned against it (%)',
      h.supplier_total, v_other_paid + h.paid_amount;
  end if;

  perform public.post_purchase(v_id);
  return v_id;
end;
$$;

------------------------------------------------------------------------------------------
-- Sales
------------------------------------------------------------------------------------------
create or replace function public.post_sale_journal(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  h public.sales;
  v_lines jsonb;
begin
  select * into h from public.sales where id = p_id;
  v_lines := jsonb_build_array(
    public.jl_dr(public.system_account('RECEIVABLE'), h.total_amount, h.customer_id, 'Sale'),
    public.jl_cr(public.system_account('SALES'), h.goods_amount - h.discount, null, 'Sales'),
    public.jl_cr(public.system_account('OTHER_INCOME'), h.transport_charge + h.labour_charge, null, 'Transport and labour charged'),
    public.jl_dr(public.system_account('COGS'), h.cost_amount, null, 'Cost of goods sold'),
    public.jl_cr(public.system_account('INVENTORY'), h.cost_amount, null, 'Goods issued')
  );
  if h.commission_amount > 0 then
    if h.broker_id is null then
      raise exception 'Choose the broker to pay commission to';
    end if;
    v_lines := v_lines
      || public.jl_dr(public.system_account('COMMISSION'), h.commission_amount, null, 'Broker commission')
      || public.jl_cr(public.system_account('PAYABLE'), h.commission_amount, h.broker_id, 'Broker commission');
  end if;
  perform public.post_journal(h.sale_date, 'SALE', h.id, 'Sale ' || h.sale_no, v_lines);
end;
$$;

create or replace function public.post_sale(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare
  h public.sales;
  r public.sale_lines;
  v_cost numeric;
  v_total_cost numeric := 0;
begin
  select * into h from public.sales where id = p_id;

  for r in select * from public.sale_lines where sale_id = p_id order by line_no loop
    v_cost := public.consume_stock(h.sale_date, r.item_id, coalesce(r.warehouse_id, h.warehouse_id), r.qty_kg, r.bags,
      'SALE', h.id, r.id, r.lot_id,
      -- revenue for lot profit: line amount less its share of discount
      r.amount - case when h.goods_amount > 0 then h.discount * r.amount / h.goods_amount else 0 end,
      h.sale_no);
    update public.sale_lines set cost_amount = v_cost where id = r.id;
    v_total_cost := v_total_cost + v_cost;
  end loop;
  update public.sales set cost_amount = v_total_cost where id = p_id;

  perform public.post_sale_journal(p_id);

  if h.received_amount > 0 then
    perform public.create_linked_money_txn('RECEIPT', h.sale_date, h.customer_id, h.received_account_id, h.received_amount,
      h.received_method, h.received_cheque_no, h.received_cheque_date, h.id, null, 'Received with ' || h.sale_no);
  end if;
end;
$$;

create or replace function public.unpost_sale(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from public.sale_returns where sale_id = p_id) then
    raise exception 'This sale has returns. Delete the returns first.';
  end if;
  perform public.remove_linked_money_txns(p_id, null);
  perform public.unpost_stock('SALE', p_id);
  perform public.unpost_journal('SALE', p_id);
end;
$$;

create or replace function public.save_sale(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_date date := (p->>'sale_date')::date;
  v_no text := nullif(p->>'sale_no', '');
  l jsonb;
  v_i int := 0;
  v_goods numeric := 0;
  v_amount numeric;
  v_other_paid numeric;
  h public.sales;
begin
  perform public.require_role('ADMIN', 'ACCOUNTANT', 'OPERATOR');
  if jsonb_array_length(coalesce(p->'lines', '[]'::jsonb)) = 0 then
    raise exception 'Add at least one item';
  end if;

  if v_id is not null then
    perform public.unpost_sale(v_id);
    delete from public.sale_lines where sale_id = v_id;
    select sale_no into v_no from public.sales where id = v_id;
  else
    v_id := gen_random_uuid();
  end if;

  insert into public.sales (id, sale_no, sale_date, customer_id, broker_id, warehouse_id, vehicle_no, driver_name, driver_phone,
    reference, notes, transport_charge, labour_charge, discount, commission_amount, received_amount, received_account_id,
    received_method, received_cheque_no, received_cheque_date)
  values (v_id, coalesce(v_no, public.next_doc_no('SAL', v_date)), v_date, (p->>'customer_id')::uuid,
    nullif(p->>'broker_id', '')::uuid, (p->>'warehouse_id')::uuid, p->>'vehicle_no', p->>'driver_name', p->>'driver_phone',
    p->>'reference', p->>'notes', coalesce(nullif(p->>'transport_charge', '')::numeric, 0), coalesce(nullif(p->>'labour_charge', '')::numeric, 0),
    coalesce(nullif(p->>'discount', '')::numeric, 0), coalesce(nullif(p->>'commission_amount', '')::numeric, 0),
    coalesce(nullif(p->>'received_amount', '')::numeric, 0), nullif(p->>'received_account_id', '')::uuid,
    coalesce(nullif(p->>'received_method', ''), 'CASH'), nullif(p->>'received_cheque_no', ''), nullif(p->>'received_cheque_date', '')::date)
  on conflict (id) do update set
    sale_date = excluded.sale_date, customer_id = excluded.customer_id, broker_id = excluded.broker_id,
    warehouse_id = excluded.warehouse_id, vehicle_no = excluded.vehicle_no, driver_name = excluded.driver_name,
    driver_phone = excluded.driver_phone, reference = excluded.reference, notes = excluded.notes,
    transport_charge = excluded.transport_charge, labour_charge = excluded.labour_charge, discount = excluded.discount,
    commission_amount = excluded.commission_amount, received_amount = excluded.received_amount,
    received_account_id = excluded.received_account_id, received_method = excluded.received_method,
    received_cheque_no = excluded.received_cheque_no, received_cheque_date = excluded.received_cheque_date, updated_at = now();

  for l in select * from jsonb_array_elements(p->'lines') loop
    v_i := v_i + 1;
    if coalesce(l->>'rate_unit', 'KG') = 'BAG' and coalesce(nullif(l->>'bags', '')::numeric, 0) <= 0 then
      raise exception 'Line %: enter the number of bags for a per-bag rate', v_i;
    end if;
    v_amount := public.line_amount(coalesce(l->>'rate_unit', 'KG'), nullif(l->>'rate', '')::numeric,
      nullif(l->>'qty_kg', '')::numeric, nullif(l->>'bags', '')::numeric);
    insert into public.sale_lines (sale_id, line_no, item_id, lot_id, warehouse_id, bags, bag_size_kg, qty_kg, rate, rate_unit, amount)
    values (v_id, v_i, (l->>'item_id')::uuid, nullif(l->>'lot_id', '')::uuid, nullif(l->>'warehouse_id', '')::uuid,
      coalesce(nullif(l->>'bags', '')::numeric, 0), coalesce(nullif(l->>'bag_size_kg', '')::numeric, 0),
      nullif(l->>'qty_kg', '')::numeric, coalesce(nullif(l->>'rate', '')::numeric, 0), coalesce(l->>'rate_unit', 'KG'), v_amount);
    v_goods := v_goods + v_amount;
  end loop;

  update public.sales set
    goods_amount = v_goods,
    total_amount = v_goods - discount + transport_charge + labour_charge
  where id = v_id
  returning * into h;

  if h.received_amount > 0 and h.received_account_id is null then
    raise exception 'Choose the cash or bank account the money was received into';
  end if;
  -- already received by separate receipts or returned: the invoice can't drop below that
  select coalesce((select sum(bs.amount) from public.bill_settlements bs join public.money_txns m on m.id = bs.money_txn_id
                   where bs.sale_id = v_id and m.linked_sale_id is distinct from v_id), 0)
       + coalesce((select sum(amount) from public.sale_returns where sale_id = v_id), 0)
  into v_other_paid;
  if h.total_amount + 0.005 < v_other_paid + h.received_amount then
    raise exception 'The invoice total (%) is less than what has already been received or returned against it (%)',
      h.total_amount, v_other_paid + h.received_amount;
  end if;

  perform public.post_sale(v_id);
  return v_id;
end;
$$;

------------------------------------------------------------------------------------------
-- Dues ageing on the whole balance: what is still owed is made up of the newest increases
------------------------------------------------------------------------------------------
create or replace function public.report_ageing(p_as_of date)
returns table (party_id uuid, name text, name_bn text, phone text, credit_limit numeric, balance numeric,
  b0 numeric, b30 numeric, b60 numeric, b90 numeric)
language sql stable as $$
  with lines as (
    select l.id, l.party_id, l.debit, l.credit, e.entry_date
    from public.journal_lines l join public.journal_entries e on e.id = l.entry_id
    where l.party_id is not null and e.entry_date <= p_as_of
  ),
  bal as (
    select party_id, sum(debit - credit) as balance from lines group by party_id having abs(sum(debit - credit)) > 0.005
  ),
  incr as (
    select ln.id, ln.party_id, ln.entry_date, b.balance,
      case when b.balance > 0 then ln.debit else ln.credit end as amt
    from lines ln join bal b on b.party_id = ln.party_id
  ),
  run as (
    select *, sum(amt) over (partition by party_id order by entry_date desc, id desc rows unbounded preceding) as cum
    from incr where amt > 0
  ),
  part as (
    select party_id, p_as_of - entry_date as age, greatest(least(amt, abs(balance) - (cum - amt)), 0) as unpaid from run
  )
  select p.id, p.name, p.name_bn, p.phone, p.credit_limit, b.balance,
    coalesce(sum(part.unpaid) filter (where part.age < 30), 0),
    coalesce(sum(part.unpaid) filter (where part.age >= 30 and part.age < 60), 0),
    coalesce(sum(part.unpaid) filter (where part.age >= 60 and part.age < 90), 0),
    coalesce(sum(part.unpaid) filter (where part.age >= 90), 0)
  from bal b
  join public.parties p on p.id = b.party_id
  left join part on part.party_id = b.party_id
  group by p.id, b.balance
  order by abs(b.balance) desc
$$;

------------------------------------------------------------------------------------------
-- Permissions for the new internal functions
------------------------------------------------------------------------------------------
revoke execute on function
  public.post_purchase_journal(uuid), public.post_sale_journal(uuid),
  public.create_linked_money_txn(text, date, uuid, uuid, numeric, text, text, date, uuid, uuid, text),
  public.remove_linked_money_txns(uuid, uuid)
from public, anon, authenticated;

------------------------------------------------------------------------------------------
-- Convert existing records: money taken at a sale / paid at a purchase becomes a linked voucher
------------------------------------------------------------------------------------------
do $$
declare r record;
begin
  for r in select s.* from public.sales s
           where s.received_amount > 0 and not exists (select 1 from public.money_txns m where m.linked_sale_id = s.id) loop
    perform public.unpost_journal('SALE', r.id);
    perform public.post_sale_journal(r.id);
    perform public.create_linked_money_txn('RECEIPT', r.sale_date, r.customer_id, r.received_account_id, r.received_amount,
      (select case when subtype = 'BANK' then 'BANK' else 'CASH' end from public.accounts where id = r.received_account_id),
      null, null, r.id, null, 'Received with ' || r.sale_no);
  end loop;

  for r in select pu.* from public.purchases pu
           where pu.paid_amount > 0 and not exists (select 1 from public.money_txns m where m.linked_purchase_id = pu.id) loop
    perform public.unpost_journal('PURCHASE', r.id);
    perform public.post_purchase_journal(r.id);
    perform public.create_linked_money_txn('PAYMENT', r.purchase_date, r.supplier_id, r.paid_account_id, r.paid_amount,
      (select case when subtype = 'BANK' then 'BANK' else 'CASH' end from public.accounts where id = r.paid_account_id),
      null, null, null, r.id, 'Paid with ' || r.purchase_no);
  end loop;
end $$;


-- ==== 0013_team_roles.sql ====
-- 0013 Team: super admin, approval of new sign-ups, invitations, department roles
--
-- Roles
--   SUPER_ADMIN  everything, and the only role that manages the team
--   ADMIN        everything except the team
--   ACCOUNTANT   money, every document, reports and setup
--   PURCHASER    purchases, purchase returns, suppliers
--   SALES        sales, sale returns, customers
--   PRODUCTION   milling batches, stock transfers and adjustments
--   OPERATOR     purchases, sales, milling and stock together (kept from earlier versions)
--   VIEWER       read-only, including the books
--
-- New sign-ups are PENDING and can see nothing until the super admin approves them, unless the
-- super admin invited their email first. Permissions live in one place: public.perm_roles().
--
-- Safe to run on a project that already has data. Run once.

------------------------------------------------------------------------------------------
-- 1. Roles become text so new roles can be added in the same script.
--    Dropping the old role functions also drops the policies built on them; all are recreated below.
------------------------------------------------------------------------------------------
drop function if exists public.require_role(variadic public.user_role[]) cascade;
drop function if exists public.has_role(variadic public.user_role[]) cascade;
drop function if exists public.app_role() cascade;

alter table public.profiles alter column role drop default;
alter table public.profiles alter column role type text using role::text;
drop type if exists public.user_role;
alter table public.profiles alter column role set default 'VIEWER';
alter table public.profiles drop constraint if exists profiles_role_valid;
alter table public.profiles add constraint profiles_role_valid
  check (role in ('SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT', 'PURCHASER', 'SALES', 'PRODUCTION', 'OPERATOR', 'VIEWER'));

-- Approval status replaces the old active flag
alter table public.profiles add column if not exists status text not null default 'PENDING';
alter table public.profiles drop constraint if exists profiles_status_valid;
alter table public.profiles add constraint profiles_status_valid check (status in ('PENDING', 'ACTIVE', 'BLOCKED'));
alter table public.profiles add column if not exists approved_by uuid references public.profiles(id) on delete set null;
alter table public.profiles add column if not exists approved_at timestamptz;
do $$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'profiles' and column_name = 'is_active') then
    update public.profiles set status = case when is_active then 'ACTIVE' else 'BLOCKED' end, approved_at = coalesce(approved_at, created_at);
    alter table public.profiles drop column is_active;
  end if;
end $$;

-- The earliest admin becomes the super admin (on a fresh install, the first sign-up does)
update public.profiles set role = 'SUPER_ADMIN'
where id = (select id from public.profiles where role = 'ADMIN' and status = 'ACTIVE' order by created_at limit 1)
  and not exists (select 1 from public.profiles where role = 'SUPER_ADMIN');

------------------------------------------------------------------------------------------
-- 2. Role and permission checks
------------------------------------------------------------------------------------------
create or replace function public.app_role()
returns text language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid() and status = 'ACTIVE'
$$;

create or replace function public.has_role(variadic roles text[])
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(public.app_role() = any(roles), false)
$$;

-- Which roles hold each permission. The app's permission list (src/app/auth.tsx) mirrors this.
create or replace function public.perm_roles(p_perm text)
returns text[] language sql immutable as $$
  select case p_perm
    when 'purchase'        then array['SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT', 'PURCHASER', 'OPERATOR']
    when 'sale'            then array['SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT', 'SALES', 'OPERATOR']
    when 'production'      then array['SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT', 'PRODUCTION', 'OPERATOR']
    when 'stock'           then array['SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT', 'PRODUCTION', 'OPERATOR']
    when 'purchase_return' then array['SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT', 'PURCHASER']
    when 'sale_return'     then array['SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT', 'SALES']
    when 'parties'         then array['SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT', 'PURCHASER', 'SALES', 'OPERATOR']
    when 'delete_doc'      then array['SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT']
    when 'reopen_batch'    then array['SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT']
    when 'money'           then array['SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT']
    when 'setup'           then array['SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT']
    when 'books'           then array['SUPER_ADMIN', 'ADMIN', 'ACCOUNTANT', 'VIEWER']
    when 'company'         then array['SUPER_ADMIN', 'ADMIN']
    when 'audit'           then array['SUPER_ADMIN', 'ADMIN']
    when 'delete_master'   then array['SUPER_ADMIN', 'ADMIN']
    when 'team'            then array['SUPER_ADMIN']
    else array[]::text[]
  end
$$;

create or replace function public.can(p_perm text)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(public.app_role() = any(public.perm_roles(p_perm)), false)
$$;

create or replace function public.require_perm(p_perm text)
returns void language plpgsql stable security definer set search_path = public as $$
begin
  if not public.can(p_perm) then
    raise exception 'You do not have permission for this action' using errcode = '42501';
  end if;
end;
$$;

------------------------------------------------------------------------------------------
-- 3. Point every document function at its permission.
--    Each function's role check is swapped in place; the rest of its body is unchanged.
------------------------------------------------------------------------------------------
do $$
declare
  m record;
  v_def text;
  v_new text;
begin
  for m in select * from (values
    ('save_purchase', 'purchase'), ('delete_purchase', 'delete_doc'),
    ('save_sale', 'sale'), ('delete_sale', 'delete_doc'),
    ('save_sale_return', 'sale_return'), ('delete_sale_return', 'sale_return'),
    ('save_purchase_return', 'purchase_return'), ('delete_purchase_return', 'purchase_return'),
    ('save_stock_transfer', 'stock'), ('delete_stock_transfer', 'stock'),
    ('save_stock_adjustment', 'stock'), ('delete_stock_adjustment', 'stock'),
    ('save_production_batch', 'production'), ('save_production_stage', 'production'),
    ('save_production_cost', 'production'), ('delete_production_cost', 'production'),
    ('complete_production_batch', 'production'), ('reopen_production_batch', 'reopen_batch'),
    ('delete_production_batch', 'delete_doc'),
    ('save_money_txn', 'money'), ('set_cheque_status', 'money'), ('delete_money_txn', 'money')
  ) as t(fn, perm) loop
    select pg_get_functiondef(p.oid) into v_def
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = m.fn;
    if v_def is null then
      raise exception 'Function % not found', m.fn;
    end if;
    v_new := regexp_replace(v_def, 'perform public\.require_(role|perm)\([^;]*\);', format('perform public.require_perm(%L);', m.perm));
    if v_new = v_def and v_def not like format('%%require_perm(%L)%%', m.perm) then
      raise exception 'Could not find the permission check in %', m.fn;
    end if;
    execute v_new;
  end loop;
end $$;

------------------------------------------------------------------------------------------
-- 4. Invitations and sign-up
------------------------------------------------------------------------------------------
create table if not exists public.team_invites (
  id uuid primary key default gen_random_uuid(),
  email text not null,
  full_name text,
  role text not null check (role in ('ADMIN', 'ACCOUNTANT', 'PURCHASER', 'SALES', 'PRODUCTION', 'OPERATOR', 'VIEWER')),
  invited_by uuid default auth.uid() references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  used_at timestamptz
);
create unique index if not exists team_invites_email_idx on public.team_invites (lower(email));

-- First sign-up: super admin. Invited email: active with the invited role. Anyone else: pending.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  inv public.team_invites;
begin
  if not exists (select 1 from public.profiles) then
    insert into public.profiles (id, full_name, email, role, status, approved_at)
    values (new.id, coalesce(new.raw_user_meta_data->>'full_name', ''), new.email, 'SUPER_ADMIN', 'ACTIVE', now())
    on conflict (id) do nothing;
    return new;
  end if;

  select * into inv from public.team_invites where lower(email) = lower(new.email) and used_at is null;
  if inv.id is not null then
    insert into public.profiles (id, full_name, email, role, status, approved_by, approved_at)
    values (new.id, coalesce(nullif(new.raw_user_meta_data->>'full_name', ''), inv.full_name, ''), new.email,
      inv.role, 'ACTIVE', inv.invited_by, now())
    on conflict (id) do nothing;
    update public.team_invites set used_at = now() where id = inv.id;
  else
    insert into public.profiles (id, full_name, email, role, status)
    values (new.id, coalesce(new.raw_user_meta_data->>'full_name', ''), new.email, 'VIEWER', 'PENDING')
    on conflict (id) do nothing;
  end if;
  return new;
end;
$$;

-- Add a member: approve them now if they already signed up, otherwise invite their email
create or replace function public.invite_member(p_email text, p_full_name text, p_role text)
returns text language plpgsql security definer set search_path = public as $$
declare
  v_profile uuid;
begin
  perform public.require_perm('team');
  if p_role = 'SUPER_ADMIN' or p_role is null then
    raise exception 'Choose a role';
  end if;
  if coalesce(trim(p_email), '') !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'Enter a valid email address';
  end if;

  select id into v_profile from public.profiles where lower(email) = lower(trim(p_email));
  if v_profile is not null then
    update public.profiles set role = p_role, status = 'ACTIVE', approved_by = auth.uid(), approved_at = now(),
      full_name = coalesce(nullif(full_name, ''), p_full_name, '')
    where id = v_profile;
    return 'APPROVED';
  end if;

  insert into public.team_invites (email, full_name, role)
  values (lower(trim(p_email)), nullif(trim(p_full_name), ''), p_role)
  on conflict (lower(email)) do update set full_name = excluded.full_name, role = excluded.role, used_at = null,
    invited_by = auth.uid(), created_at = now();
  return 'INVITED';
end;
$$;

-- Team changes: only the super admin, and there must always be an active super admin left
create or replace function public.guard_profile_change()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'UPDATE' then
    if (new.role is distinct from old.role or new.status is distinct from old.status)
       and old.role = 'SUPER_ADMIN'
       and (new.role <> 'SUPER_ADMIN' or new.status <> 'ACTIVE')
       and not exists (select 1 from public.profiles where role = 'SUPER_ADMIN' and status = 'ACTIVE' and id <> old.id) then
      raise exception 'There must always be one active super admin';
    end if;
    if new.status = 'ACTIVE' and old.status <> 'ACTIVE' then
      new.approved_by := coalesce(auth.uid(), new.approved_by);
      new.approved_at := now();
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_guard_profile on public.profiles;
create trigger trg_guard_profile before update on public.profiles
for each row execute function public.guard_profile_change();

------------------------------------------------------------------------------------------
-- 5. Row-level security, rebuilt on the permission list
------------------------------------------------------------------------------------------
alter table public.team_invites enable row level security;

do $$
declare
  t text;
  r record;
begin
  -- clear every policy on our tables, then recreate
  for r in select schemaname, tablename, policyname from pg_policies where schemaname = 'public' loop
    execute format('drop policy %I on %I.%I', r.policyname, r.schemaname, r.tablename);
  end loop;

  foreach t in array array[
    'company_settings', 'accounts', 'parties', 'items', 'warehouses',
    'lots', 'stock_movements', 'lot_allocations', 'stock_transfers', 'stock_adjustments',
    'purchases', 'purchase_lines', 'sales', 'sale_lines', 'sale_returns', 'purchase_returns',
    'production_batches', 'production_inputs', 'production_stages', 'production_costs', 'production_outputs',
    'money_txns', 'bill_settlements'
  ] loop
    execute format('create policy "read %1$s" on public.%1$I for select to authenticated using (public.app_role() is not null)', t);
  end loop;

  foreach t in array array['journal_entries', 'journal_lines'] loop
    execute format('create policy "read %1$s" on public.%1$I for select to authenticated using (public.can(''books''))', t);
  end loop;
end $$;

-- Everyone sees their own profile (so a pending user can see they are pending); active users see the team
create policy "read profiles" on public.profiles for select to authenticated
  using (id = auth.uid() or public.app_role() is not null);
create policy "team updates profiles" on public.profiles for update to authenticated
  using (public.can('team')) with check (public.can('team'));

create policy "team manages invites" on public.team_invites for all to authenticated
  using (public.can('team')) with check (public.can('team'));

create policy "read audit" on public.audit_log for select to authenticated using (public.can('audit'));

create policy "update company" on public.company_settings for update to authenticated
  using (public.can('company')) with check (public.can('company'));

create policy "insert accounts" on public.accounts for insert to authenticated with check (public.can('setup'));
create policy "update accounts" on public.accounts for update to authenticated using (public.can('setup')) with check (public.can('setup'));
create policy "delete accounts" on public.accounts for delete to authenticated using (public.can('delete_master') and not is_system);

create policy "insert parties" on public.parties for insert to authenticated with check (public.can('parties'));
create policy "update parties" on public.parties for update to authenticated using (public.can('parties')) with check (public.can('parties'));
create policy "delete parties" on public.parties for delete to authenticated using (public.can('delete_master'));

create policy "insert items" on public.items for insert to authenticated with check (public.can('setup'));
create policy "update items" on public.items for update to authenticated using (public.can('setup')) with check (public.can('setup'));
create policy "delete items" on public.items for delete to authenticated using (public.can('delete_master'));

create policy "insert warehouses" on public.warehouses for insert to authenticated with check (public.can('setup'));
create policy "update warehouses" on public.warehouses for update to authenticated using (public.can('setup')) with check (public.can('setup'));
create policy "delete warehouses" on public.warehouses for delete to authenticated using (public.can('delete_master'));

------------------------------------------------------------------------------------------
-- 6. Function permissions
------------------------------------------------------------------------------------------
revoke execute on function public.handle_new_user(), public.guard_profile_change() from public, anon, authenticated;
revoke execute on function public.invite_member(text, text, text) from public, anon;
grant execute on function public.invite_member(text, text, text) to authenticated;

drop trigger if exists audit_team_invites on public.team_invites;
create trigger audit_team_invites after insert or update or delete on public.team_invites
for each row execute function public.audit_row();


-- ==== 0014_rice_sections.sql ====
-- 0014 Rice sections: Dryer and Sorter batches, unsorted rice, by-products at current price
--
--   DRYER  batch: paddy (MATERIAL) [+ own husk burned as fuel, sacks... (CONSUMABLE)]
--                 → unsorted rice + by-products (husk, bran)
--   SORTER batch: unsorted rice (MATERIAL; own or bought from other mills) [+ CONSUMABLE]
--                 → sorted rice grades + by-products (broken, polish/reject)
--
-- Costing: by-products are valued at their current price per kg (items.standard_price);
-- the main products (unsorted rice / sorted rice) carry the rest of the batch cost.
--
-- Safe to run on a project that already has data. Run once.

------------------------------------------------------------------------------------------
-- 1. Item category and batch status become text so new values work in this script.
--    Views built on those columns are dropped here and recreated below.
------------------------------------------------------------------------------------------
drop view if exists public.v_production_batches;
drop view if exists public.v_lot_profit;
drop view if exists public.v_stock_summary;
drop view if exists public.v_lots;

alter table public.items alter column category type text using category::text;
drop type if exists public.item_category;
alter table public.items drop constraint if exists items_category_valid;
alter table public.items add constraint items_category_valid
  check (category in ('PADDY', 'UNSORTED', 'RICE', 'BYPRODUCT', 'PACKAGING', 'OTHER'));

alter table public.production_batches alter column status drop default;
alter table public.production_batches alter column status type text using
  case when status::text in ('SOAKING', 'DRYING', 'MILLING') then 'RUNNING' else status::text end;
drop type if exists public.production_status;
alter table public.production_batches alter column status set default 'RUNNING';
alter table public.production_batches drop constraint if exists production_batches_status_valid;
alter table public.production_batches add constraint production_batches_status_valid
  check (status in ('RUNNING', 'COMPLETED', 'CANCELLED'));

alter table public.production_batches add column if not exists kind text not null default 'DRYER';
alter table public.production_batches drop constraint if exists production_batches_kind_valid;
alter table public.production_batches add constraint production_batches_kind_valid check (kind in ('DRYER', 'SORTER'));
alter table public.production_batches add column if not exists byproduct_value numeric(14,2) not null default 0;

alter table public.production_inputs add column if not exists purpose text not null default 'MATERIAL';
alter table public.production_inputs drop constraint if exists production_inputs_purpose_valid;
alter table public.production_inputs add constraint production_inputs_purpose_valid check (purpose in ('MATERIAL', 'CONSUMABLE'));

------------------------------------------------------------------------------------------
-- 2. Starting items and current-price history
------------------------------------------------------------------------------------------
insert into public.items (code, name, name_bn, category, default_bag_kg, standard_price) values
  ('U-01', 'Unsorted Rice (Coarse)', 'আনসর্টেড চাল (মোটা)', 'UNSORTED', 50, 45),
  ('U-02', 'Unsorted Rice (Fine)', 'আনসর্টেড চাল (চিকন)', 'UNSORTED', 50, 62),
  ('B-04', 'Polish / Reject', 'পলিশ / রিজেক্ট', 'BYPRODUCT', 40, 15)
on conflict (code) do nothing;

create table if not exists public.item_price_history (
  id bigint generated always as identity primary key,
  item_id uuid not null references public.items(id) on delete cascade,
  old_price numeric(14,4),
  new_price numeric(14,4) not null,
  changed_by uuid default auth.uid() references public.profiles(id) on delete set null,
  changed_at timestamptz not null default now()
);
create index if not exists item_price_history_item_idx on public.item_price_history (item_id, changed_at desc);

create or replace function public.log_item_price()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' or new.standard_price is distinct from old.standard_price then
    insert into public.item_price_history (item_id, old_price, new_price)
    values (new.id, case when tg_op = 'UPDATE' then old.standard_price end, new.standard_price);
  end if;
  return null;
end;
$$;

drop trigger if exists trg_item_price on public.items;
create trigger trg_item_price after insert or update of standard_price on public.items
for each row execute function public.log_item_price();

-- record today's prices as the starting point
insert into public.item_price_history (item_id, new_price, changed_at)
select i.id, i.standard_price, coalesce(i.created_at, now()) from public.items i
where not exists (select 1 from public.item_price_history h where h.item_id = i.id);

alter table public.item_price_history enable row level security;
drop policy if exists "read item prices" on public.item_price_history;
create policy "read item prices" on public.item_price_history for select to authenticated using (public.app_role() is not null);

------------------------------------------------------------------------------------------
-- 3. Batches
------------------------------------------------------------------------------------------
create or replace function public.require_open_batch(p_id uuid)
returns public.production_batches language plpgsql security definer set search_path = public as $$
declare b public.production_batches;
begin
  select * into b from public.production_batches where id = p_id;
  if b.id is null then
    raise exception 'Batch not found';
  end if;
  if b.status <> 'RUNNING' then
    raise exception 'Batch % is %. Reopen it first.', b.batch_no, lower(b.status);
  end if;
  return b;
end;
$$;

-- Create or edit a batch: section + materials + consumables (own husk as fuel, sacks...)
create or replace function public.save_production_batch(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_date date := (p->>'start_date')::date;
  v_kind text := coalesce(nullif(p->>'kind', ''), 'DRYER');
  v_material_cat text;
  b public.production_batches;
  l jsonb;
  v_cost numeric;
  v_total numeric := 0;
  v_kg numeric := 0;
  v_input_id uuid;
  v_purpose text;
  v_cat text;
  v_name text;
begin
  perform public.require_perm('production');
  if v_kind not in ('DRYER', 'SORTER') then
    raise exception 'Choose the section';
  end if;
  v_material_cat := case v_kind when 'DRYER' then 'PADDY' else 'UNSORTED' end;
  if not exists (select 1 from jsonb_array_elements(coalesce(p->'inputs', '[]'::jsonb)) x
                 where coalesce(nullif(x->>'purpose', ''), 'MATERIAL') = 'MATERIAL') then
    raise exception '%', case v_kind when 'DRYER' then 'Add the paddy going into this batch'
                                     else 'Add the unsorted rice going into this batch' end;
  end if;

  if v_id is not null then
    perform public.require_open_batch(v_id);
    perform public.unpost_stock('PRODUCTION_INPUT', v_id);
    perform public.unpost_journal('PRODUCTION_INPUT', v_id);
    delete from public.production_inputs where batch_id = v_id;
    update public.production_batches set
      kind = v_kind, start_date = v_date, input_warehouse_id = (p->>'input_warehouse_id')::uuid,
      output_warehouse_id = (p->>'output_warehouse_id')::uuid, notes = p->>'notes', updated_at = now()
    where id = v_id returning * into b;
  else
    insert into public.production_batches (batch_no, kind, start_date, status, input_warehouse_id, output_warehouse_id, notes)
    values (public.next_doc_no(case v_kind when 'DRYER' then 'DRY' else 'SOR' end, v_date), v_kind, v_date, 'RUNNING',
      (p->>'input_warehouse_id')::uuid, (p->>'output_warehouse_id')::uuid, p->>'notes')
    returning * into b;
  end if;

  for l in select * from jsonb_array_elements(p->'inputs') loop
    v_purpose := coalesce(nullif(l->>'purpose', ''), 'MATERIAL');
    select category, name into v_cat, v_name from public.items where id = (l->>'item_id')::uuid;
    if v_purpose = 'MATERIAL' and v_cat <> v_material_cat then
      raise exception '% is not %', v_name, case v_kind when 'DRYER' then 'paddy' else 'unsorted rice' end;
    end if;
    insert into public.production_inputs (batch_id, item_id, lot_id, bags, qty_kg, purpose)
    values (b.id, (l->>'item_id')::uuid, nullif(l->>'lot_id', '')::uuid, coalesce(nullif(l->>'bags', '')::numeric, 0),
      nullif(l->>'qty_kg', '')::numeric, v_purpose)
    returning id into v_input_id;
    v_cost := public.consume_stock(b.start_date, (l->>'item_id')::uuid, b.input_warehouse_id, nullif(l->>'qty_kg', '')::numeric,
      coalesce(nullif(l->>'bags', '')::numeric, 0), 'PRODUCTION_INPUT', b.id, v_input_id, nullif(l->>'lot_id', '')::uuid, null, b.batch_no);
    update public.production_inputs set cost = v_cost where id = v_input_id;
    v_total := v_total + v_cost;
    if v_purpose = 'MATERIAL' then
      v_kg := v_kg + nullif(l->>'qty_kg', '')::numeric;
    end if;
  end loop;

  -- input_kg counts the material only; input_cost includes consumables
  update public.production_batches set input_kg = v_kg, input_cost = v_total where id = b.id;

  perform public.post_journal(b.start_date, 'PRODUCTION_INPUT', b.id, 'Into batch ' || b.batch_no, jsonb_build_array(
    public.jl_dr(public.system_account('WIP'), v_total),
    public.jl_cr(public.system_account('INVENTORY'), v_total)));
  return b.id;
end;
$$;

-- Stage details are kept for old batches; they no longer drive the status
create or replace function public.save_production_stage(p jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare
  b public.production_batches := public.require_open_batch((p->>'batch_id')::uuid);
begin
  perform public.require_perm('production');
  update public.production_stages set
    start_date = nullif(p->>'start_date', '')::date,
    end_date = nullif(p->>'end_date', '')::date,
    input_kg = nullif(p->>'input_kg', '')::numeric,
    output_kg = nullif(p->>'output_kg', '')::numeric,
    moisture_pct = nullif(p->>'moisture_pct', '')::numeric,
    notes = p->>'notes'
  where batch_id = b.id and stage = p->>'stage';
end;
$$;

-- Finish a batch: p = {batch_id, completed_date, outputs: [{item_id, bags, bag_size_kg, qty_kg}]}
-- By-products take their current price; main products share the rest by relative price (or weight).
create or replace function public.complete_production_batch(p jsonb)
returns void language plpgsql security definer set search_path = public as $$
declare
  b public.production_batches := public.require_open_batch((p->>'batch_id')::uuid);
  v_date date := (p->>'completed_date')::date;
  v_main_cat text := case b.kind when 'DRYER' then 'UNSORTED' else 'RICE' end;
  v_total numeric;
  v_by_value numeric;
  v_rest numeric;
  v_base numeric;
  v_use_price boolean;
  v_allocated numeric := 0;
  v_share numeric;
  v_n int;
  v_i int := 0;
  o record;
  v_lot uuid;
begin
  perform public.require_perm('production');
  if jsonb_array_length(coalesce(p->'outputs', '[]'::jsonb)) = 0 then
    raise exception 'Add what came out of this batch';
  end if;

  delete from public.production_outputs where batch_id = b.id;
  insert into public.production_outputs (batch_id, item_id, bags, bag_size_kg, qty_kg)
  select b.id, (x->>'item_id')::uuid, coalesce(nullif(x->>'bags', '')::numeric, 0), coalesce(nullif(x->>'bag_size_kg', '')::numeric, 0),
    nullif(x->>'qty_kg', '')::numeric
  from jsonb_array_elements(p->'outputs') x;

  if exists (select 1 from public.production_outputs po join public.items i on i.id = po.item_id
             where po.batch_id = b.id and i.category not in (v_main_cat, 'BYPRODUCT')) then
    raise exception '%', case b.kind when 'DRYER' then 'The dryer section gives unsorted rice and by-products only'
                                     else 'The sorter section gives sorted rice and by-products only' end;
  end if;
  if not exists (select 1 from public.production_outputs po join public.items i on i.id = po.item_id
                 where po.batch_id = b.id and i.category = v_main_cat) then
    raise exception '%', case b.kind when 'DRYER' then 'Add the unsorted rice that came out'
                                     else 'Add the sorted rice that came out' end;
  end if;

  v_total := b.input_cost + (select coalesce(sum(amount), 0) from public.production_costs where batch_id = b.id);

  -- by-products at current price
  for o in select po.id, po.qty_kg, i.standard_price from public.production_outputs po join public.items i on i.id = po.item_id
           where po.batch_id = b.id and i.category = 'BYPRODUCT' loop
    v_share := round(o.qty_kg * o.standard_price, 2);
    update public.production_outputs set cost_share = v_share, unit_cost = round(o.standard_price, 6) where id = o.id;
  end loop;
  select coalesce(sum(po.cost_share), 0) into v_by_value from public.production_outputs po join public.items i on i.id = po.item_id
  where po.batch_id = b.id and i.category = 'BYPRODUCT';

  v_rest := v_total - v_by_value;
  if v_rest < 0 then
    raise exception 'The by-products (%) are worth more than the whole batch cost (%). Check their current prices.', v_by_value, v_total;
  end if;

  -- main products share the rest: by current price, or by weight if no prices
  select sum(po.qty_kg * i.standard_price), count(*) into v_base, v_n
  from public.production_outputs po join public.items i on i.id = po.item_id
  where po.batch_id = b.id and i.category = v_main_cat;
  v_use_price := coalesce(v_base, 0) > 0;
  if not v_use_price then
    select sum(po.qty_kg) into v_base from public.production_outputs po join public.items i on i.id = po.item_id
    where po.batch_id = b.id and i.category = v_main_cat;
  end if;
  for o in select po.id, po.qty_kg, i.standard_price from public.production_outputs po join public.items i on i.id = po.item_id
           where po.batch_id = b.id and i.category = v_main_cat order by po.qty_kg * i.standard_price, po.qty_kg loop
    v_i := v_i + 1;
    if v_i = v_n then
      v_share := v_rest - v_allocated;  -- last line takes the rounding remainder
    else
      v_share := round(v_rest * (case when v_use_price then o.qty_kg * o.standard_price else o.qty_kg end) / v_base, 2);
    end if;
    v_allocated := v_allocated + v_share;
    update public.production_outputs set cost_share = v_share, unit_cost = round(v_share / o.qty_kg, 6) where id = o.id;
  end loop;

  for o in select po.* from public.production_outputs po where po.batch_id = b.id loop
    v_lot := public.receive_stock(v_date, o.item_id, b.output_warehouse_id, o.qty_kg, o.bags, o.bag_size_kg,
      o.cost_share / o.qty_kg, 'PRODUCTION', b.id, o.id, null, b.batch_no);
    update public.production_outputs set lot_id = v_lot where id = o.id;
  end loop;

  perform public.post_journal(v_date, 'PRODUCTION', b.id, 'Batch ' || b.batch_no || ' completed', jsonb_build_array(
    public.jl_dr(public.system_account('INVENTORY'), v_total),
    public.jl_cr(public.system_account('WIP'), v_total)));

  update public.production_batches set
    status = 'COMPLETED', completed_date = v_date,
    output_kg = (select sum(qty_kg) from public.production_outputs where batch_id = b.id),
    processing_cost = v_total - input_cost, byproduct_value = v_by_value, updated_at = now()
  where id = b.id;
end;
$$;

create or replace function public.reopen_production_batch(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.require_perm('reopen_batch');
  perform public.unpost_stock('PRODUCTION', p_id);
  perform public.unpost_journal('PRODUCTION', p_id);
  delete from public.production_outputs where batch_id = p_id;
  update public.production_batches set status = 'RUNNING', completed_date = null, output_kg = 0, byproduct_value = 0, updated_at = now()
  where id = p_id;
end;
$$;

------------------------------------------------------------------------------------------
-- 4. Views
------------------------------------------------------------------------------------------
create view public.v_stock_summary with (security_invoker = true) as
select
  i.id as item_id, i.name as item_name, i.name_bn as item_name_bn, i.category,
  w.id as warehouse_id, w.name as warehouse_name, w.name_bn as warehouse_name_bn,
  sum(l.remaining_kg) as qty_kg,
  sum(l.remaining_bags) as bags,
  round(sum(l.remaining_kg * l.unit_cost), 2) as value,
  case when sum(l.remaining_kg) > 0 then round(sum(l.remaining_kg * l.unit_cost) / sum(l.remaining_kg), 4) else 0 end as avg_cost,
  i.reorder_level_kg,
  i.standard_price as current_price,
  round(sum(l.remaining_kg) * i.standard_price, 2) as value_at_current_price
from public.lots l
join public.items i on i.id = l.item_id
join public.warehouses w on w.id = l.warehouse_id
where l.remaining_kg > 0.0005
group by i.id, w.id;

create view public.v_lots with (security_invoker = true) as
select
  l.*, i.name as item_name, i.name_bn as item_name_bn, i.category,
  w.name as warehouse_name, w.name_bn as warehouse_name_bn
from public.lots l
join public.items i on i.id = l.item_id
join public.warehouses w on w.id = l.warehouse_id;

create view public.v_lot_profit with (security_invoker = true) as
with recursive tree as (
  select id as root_id, id as lot_id from public.lots where parent_lot_id is null
  union all
  select t.root_id, l.id from public.lots l join tree t on l.parent_lot_id = t.lot_id
),
alloc as (
  select t.root_id,
    sum(a.qty_kg) filter (where a.source_type = 'SALE') as sold_kg,
    sum(a.revenue) filter (where a.source_type = 'SALE') as revenue,
    sum(a.cost) filter (where a.source_type = 'SALE') as cost_of_sold,
    sum(a.qty_kg) filter (where a.source_type = 'PRODUCTION_INPUT' and coalesce(pi.purpose, 'MATERIAL') = 'MATERIAL') as milled_kg,
    sum(a.qty_kg) filter (where a.source_type = 'PRODUCTION_INPUT' and pi.purpose = 'CONSUMABLE') as used_kg,
    sum(a.qty_kg) filter (where a.source_type in ('ADJUSTMENT', 'PURCHASE_RETURN')) as other_out_kg
  from tree t
  join public.lot_allocations a on a.lot_id = t.lot_id
  left join public.production_inputs pi on a.source_type = 'PRODUCTION_INPUT' and pi.id = a.source_line_id
  group by t.root_id
),
remain as (
  select t.root_id, sum(l.remaining_kg) as remaining_kg, sum(l.remaining_kg * l.unit_cost) as remaining_value
  from tree t join public.lots l on l.id = t.lot_id
  group by t.root_id
)
select
  l.id, l.lot_no, l.source_type, l.source_id, l.received_date, l.item_id, i.name as item_name, i.category,
  l.warehouse_id, w.name as warehouse_name,
  coalesce(pa.name, pb.batch_no) as source_label,
  pb.kind as batch_kind,
  l.qty_kg, l.unit_cost, round(l.qty_kg * l.unit_cost, 2) as total_cost,
  coalesce(a.sold_kg, 0) as sold_kg, coalesce(a.revenue, 0) as revenue, coalesce(a.cost_of_sold, 0) as cost_of_sold,
  coalesce(a.revenue, 0) - coalesce(a.cost_of_sold, 0) as profit,
  case when coalesce(a.revenue, 0) > 0 then round(100 * (a.revenue - a.cost_of_sold) / a.revenue, 2) end as margin_pct,
  coalesce(a.milled_kg, 0) as milled_kg, coalesce(a.used_kg, 0) as used_kg, coalesce(a.other_out_kg, 0) as other_out_kg,
  coalesce(r.remaining_kg, 0) as remaining_kg, round(coalesce(r.remaining_value, 0), 2) as remaining_value
from public.lots l
join public.items i on i.id = l.item_id
join public.warehouses w on w.id = l.warehouse_id
left join alloc a on a.root_id = l.id
left join remain r on r.root_id = l.id
left join public.purchases pu on l.source_type = 'PURCHASE' and pu.id = l.source_id
left join public.parties pa on pa.id = pu.supplier_id
left join public.production_batches pb on l.source_type = 'PRODUCTION' and pb.id = l.source_id
where l.parent_lot_id is null;

-- Batch summary per section: yield = main product kg / material kg; cost per kg of the main product
create view public.v_production_batches with (security_invoker = true) as
select
  b.*,
  b.input_cost + b.processing_cost as total_cost,
  coalesce(inp.material_cost, 0) as material_cost,
  coalesce(inp.consumable_cost, 0) as consumable_cost,
  coalesce(o.main_kg, 0) as main_kg,
  coalesce(o.main_cost, 0) as main_cost,
  coalesce(o.byproduct_kg, 0) as byproduct_kg,
  case when b.input_kg > 0 and coalesce(o.main_kg, 0) > 0 then round(100 * o.main_kg / b.input_kg, 2) end as main_yield_pct,
  case when b.input_kg > 0 and b.output_kg > 0 then round(100 * b.output_kg / b.input_kg, 2) end as total_yield_pct,
  case when coalesce(o.main_kg, 0) > 0 then round(o.main_cost / o.main_kg, 4) end as main_cost_per_kg,
  w1.name as input_warehouse_name, w2.name as output_warehouse_name
from public.production_batches b
left join (
  select batch_id,
    sum(cost) filter (where purpose = 'MATERIAL') as material_cost,
    sum(cost) filter (where purpose = 'CONSUMABLE') as consumable_cost
  from public.production_inputs group by batch_id
) inp on inp.batch_id = b.id
left join (
  select po.batch_id,
    sum(po.qty_kg) filter (where i.category <> 'BYPRODUCT') as main_kg,
    sum(po.cost_share) filter (where i.category <> 'BYPRODUCT') as main_cost,
    sum(po.qty_kg) filter (where i.category = 'BYPRODUCT') as byproduct_kg
  from public.production_outputs po join public.items i on i.id = po.item_id
  group by po.batch_id
) o on o.batch_id = b.id
join public.warehouses w1 on w1.id = b.input_warehouse_id
join public.warehouses w2 on w2.id = b.output_warehouse_id;

------------------------------------------------------------------------------------------
-- 5. Dashboard figures: running batches by section, unsorted rice stock
------------------------------------------------------------------------------------------
create or replace function public.dashboard_stats(p_from date, p_to date)
returns jsonb language sql stable as $$
  select jsonb_build_object(
    'cash', (select coalesce(sum(l.debit - l.credit), 0) from public.journal_lines l join public.accounts a on a.id = l.account_id where a.subtype = 'CASH'),
    'bank', (select coalesce(sum(l.debit - l.credit), 0) from public.journal_lines l join public.accounts a on a.id = l.account_id where a.subtype = 'BANK'),
    'receivable', (select coalesce(sum(balance), 0) from public.v_party_balances where balance > 0),
    'payable', (select coalesce(-sum(balance), 0) from public.v_party_balances where balance < 0),
    'stock_value', (select coalesce(sum(remaining_kg * unit_cost), 0) from public.lots where remaining_kg > 0),
    'paddy_kg', (select coalesce(sum(l.remaining_kg), 0) from public.lots l join public.items i on i.id = l.item_id where i.category = 'PADDY'),
    'unsorted_kg', (select coalesce(sum(l.remaining_kg), 0) from public.lots l join public.items i on i.id = l.item_id where i.category = 'UNSORTED'),
    'rice_kg', (select coalesce(sum(l.remaining_kg), 0) from public.lots l join public.items i on i.id = l.item_id where i.category = 'RICE'),
    'byproduct_kg', (select coalesce(sum(l.remaining_kg), 0) from public.lots l join public.items i on i.id = l.item_id where i.category = 'BYPRODUCT'),
    'open_batches', (select count(*) from public.production_batches where status = 'RUNNING'),
    'sales', (select coalesce(sum(total_amount), 0) from public.sales where sale_date between p_from and p_to),
    'purchases', (select coalesce(sum(total_cost), 0) from public.purchases where purchase_date between p_from and p_to),
    'expenses', (select coalesce(sum(amount), 0) from public.money_txns where txn_type = 'EXPENSE' and txn_date between p_from and p_to and coalesce(cheque_status, '') <> 'BOUNCED'),
    'profit', (select coalesce(sum(case when type = 'INCOME' then amount else -amount end), 0) from public.report_profit_loss(p_from, p_to)),
    'pending_cheques', (select count(*) from public.money_txns where cheque_status = 'PENDING'),
    'trend', (
      select coalesce(jsonb_agg(jsonb_build_object('month', to_char(m, 'YYYY-MM'), 'sales', s, 'purchases', pu) order by m), '[]'::jsonb)
      from (
        select m,
          (select coalesce(sum(total_amount), 0) from public.sales where date_trunc('month', sale_date) = m) as s,
          (select coalesce(sum(total_cost), 0) from public.purchases where date_trunc('month', purchase_date) = m) as pu
        from generate_series(date_trunc('month', p_to::timestamp) - interval '5 months', date_trunc('month', p_to::timestamp), interval '1 month') m
      ) x
    )
  )
$$;

revoke execute on function public.log_item_price() from public, anon, authenticated;
revoke execute on function public.require_open_batch(uuid) from public, anon, authenticated;


-- ==== 0015_sales_orders.sql ====
-- 0015 Sales orders: a customer's order with their PO (purchase order) number, delivered by one or more
-- sales invoices. Invoices carry the PO number so it prints on the bill and challan, and each order shows
-- ordered vs delivered vs remaining for order tracking.

------------------------------------------------------------------------------------------
-- 1. Tables
------------------------------------------------------------------------------------------
create table if not exists public.sales_orders (
  id uuid primary key default gen_random_uuid(),
  order_no text not null unique,                    -- our number, ORD-2026-00001
  order_date date not null,
  customer_id uuid not null references public.parties(id),
  po_number text,                                   -- the customer's PO number, printed on our bills
  po_date date,
  delivery_date date,                               -- promised / expected delivery
  warehouse_id uuid references public.warehouses(id),
  delivery_address text,
  notes text,
  status text not null default 'OPEN' check (status in ('OPEN', 'CLOSED', 'CANCELLED')),
  goods_amount numeric(14,2) not null default 0,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists sales_orders_customer_idx on public.sales_orders (customer_id);
create index if not exists sales_orders_date_idx on public.sales_orders (order_date);
create index if not exists sales_orders_po_idx on public.sales_orders (po_number);

create table if not exists public.sales_order_lines (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.sales_orders(id) on delete cascade,
  line_no int not null,
  item_id uuid not null references public.items(id),
  bags numeric(12,2) not null default 0,
  bag_size_kg numeric(10,3) not null default 0,
  qty_kg numeric(14,3) not null check (qty_kg > 0),
  rate numeric(14,4) not null default 0,            -- agreed price, can be left 0
  rate_unit text not null default 'KG' check (rate_unit in ('KG', 'BAG')),
  amount numeric(14,2) not null default 0,
  unique (order_id, item_id)
);

create index if not exists sales_order_lines_order_idx on public.sales_order_lines (order_id);

-- Invoices: which order they deliver, and the customer's PO number (copied from the order, or typed in)
alter table public.sales add column if not exists order_id uuid references public.sales_orders(id);
alter table public.sales add column if not exists po_number text;
alter table public.sales add column if not exists po_date date;
create index if not exists sales_order_idx on public.sales (order_id);

------------------------------------------------------------------------------------------
-- 2. Saving, closing, deleting orders
------------------------------------------------------------------------------------------
create or replace function public.save_sales_order(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_date date := (p->>'order_date')::date;
  v_no text;
  v_customer uuid := nullif(p->>'customer_id', '')::uuid;
  l jsonb;
  v_i int := 0;
  v_amount numeric;
  v_goods numeric := 0;
  v_status text;
begin
  perform public.require_perm('sale');
  if v_customer is null then
    raise exception 'Choose the customer';
  end if;
  if v_date is null then
    raise exception 'Enter the order date';
  end if;
  if jsonb_array_length(coalesce(p->'lines', '[]'::jsonb)) = 0 then
    raise exception 'Add at least one item';
  end if;

  if v_id is not null then
    select order_no, status into v_no, v_status from public.sales_orders where id = v_id;
    if v_no is null then
      raise exception 'Order not found';
    end if;
    if v_status = 'CANCELLED' then
      raise exception 'This order is cancelled; reopen it before editing';
    end if;
    if exists (select 1 from public.sales where order_id = v_id and customer_id <> v_customer) then
      raise exception 'Invoices for this order are made out to another customer; the customer cannot be changed';
    end if;
    delete from public.sales_order_lines where order_id = v_id;
  else
    v_id := gen_random_uuid();
    v_no := public.next_doc_no('ORD', v_date);
  end if;

  insert into public.sales_orders (id, order_no, order_date, customer_id, po_number, po_date, delivery_date,
    warehouse_id, delivery_address, notes)
  values (v_id, v_no, v_date, v_customer, nullif(trim(p->>'po_number'), ''), nullif(p->>'po_date', '')::date,
    nullif(p->>'delivery_date', '')::date, nullif(p->>'warehouse_id', '')::uuid, nullif(p->>'delivery_address', ''),
    nullif(p->>'notes', ''))
  on conflict (id) do update set
    order_date = excluded.order_date, customer_id = excluded.customer_id, po_number = excluded.po_number,
    po_date = excluded.po_date, delivery_date = excluded.delivery_date, warehouse_id = excluded.warehouse_id,
    delivery_address = excluded.delivery_address, notes = excluded.notes, updated_at = now();

  for l in select * from jsonb_array_elements(p->'lines') loop
    v_i := v_i + 1;
    if nullif(l->>'item_id', '') is null then
      raise exception 'Line %: choose an item', v_i;
    end if;
    if coalesce(nullif(l->>'qty_kg', '')::numeric, 0) <= 0 then
      raise exception 'Line %: enter the ordered weight', v_i;
    end if;
    if exists (select 1 from public.sales_order_lines where order_id = v_id and item_id = (l->>'item_id')::uuid) then
      raise exception 'Line %: this item is already on the order; put the whole quantity on one line', v_i;
    end if;
    if coalesce(l->>'rate_unit', 'KG') = 'BAG' and coalesce(nullif(l->>'rate', '')::numeric, 0) > 0
       and coalesce(nullif(l->>'bags', '')::numeric, 0) <= 0 then
      raise exception 'Line %: enter the number of bags for a per-bag rate', v_i;
    end if;
    v_amount := round(coalesce(nullif(l->>'rate', '')::numeric, 0) *
      case when coalesce(l->>'rate_unit', 'KG') = 'BAG' then coalesce(nullif(l->>'bags', '')::numeric, 0)
           else nullif(l->>'qty_kg', '')::numeric end, 2);
    insert into public.sales_order_lines (order_id, line_no, item_id, bags, bag_size_kg, qty_kg, rate, rate_unit, amount)
    values (v_id, v_i, (l->>'item_id')::uuid, coalesce(nullif(l->>'bags', '')::numeric, 0),
      coalesce(nullif(l->>'bag_size_kg', '')::numeric, 0), (l->>'qty_kg')::numeric,
      coalesce(nullif(l->>'rate', '')::numeric, 0), coalesce(l->>'rate_unit', 'KG'), v_amount);
    v_goods := v_goods + v_amount;
  end loop;

  update public.sales_orders set goods_amount = v_goods where id = v_id;
  -- invoices already made keep showing the order's current PO number
  update public.sales s set po_number = o.po_number, po_date = o.po_date
  from public.sales_orders o where o.id = v_id and s.order_id = v_id;
  return v_id;
end;
$$;

-- OPEN: still to deliver. CLOSED: finished (fully delivered, or the rest will not be sent). CANCELLED: called off.
create or replace function public.set_sales_order_status(p_id uuid, p_status text)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.require_perm('sale');
  if p_status not in ('OPEN', 'CLOSED', 'CANCELLED') then
    raise exception 'Unknown order status %', p_status;
  end if;
  if p_status = 'CANCELLED' and exists (select 1 from public.sales where order_id = p_id) then
    raise exception 'Goods have already been delivered on this order; close it instead of cancelling';
  end if;
  update public.sales_orders set status = p_status, updated_at = now() where id = p_id;
  if not found then
    raise exception 'Order not found';
  end if;
end;
$$;

create or replace function public.delete_sales_order(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public.require_perm('delete_doc');
  if exists (select 1 from public.sales where order_id = p_id) then
    raise exception 'Invoices have been made against this order; delete them first, or cancel/close the order';
  end if;
  delete from public.sales_orders where id = p_id;
end;
$$;

------------------------------------------------------------------------------------------
-- 3. Invoices take the order and PO number (save_sale from 0012, with order_id/po_number added)
------------------------------------------------------------------------------------------
create or replace function public.save_sale(p jsonb)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := nullif(p->>'id', '')::uuid;
  v_date date := (p->>'sale_date')::date;
  v_no text := nullif(p->>'sale_no', '');
  v_order uuid := nullif(p->>'order_id', '')::uuid;
  v_po text := nullif(trim(p->>'po_number'), '');
  v_po_date date := nullif(p->>'po_date', '')::date;
  o public.sales_orders;
  l jsonb;
  v_i int := 0;
  v_goods numeric := 0;
  v_amount numeric;
  v_other_paid numeric;
  h public.sales;
begin
  perform public.require_perm('sale');
  if jsonb_array_length(coalesce(p->'lines', '[]'::jsonb)) = 0 then
    raise exception 'Add at least one item';
  end if;

  if v_order is not null then
    select * into o from public.sales_orders where id = v_order;
    if o.id is null then
      raise exception 'Order not found';
    end if;
    if o.customer_id <> (p->>'customer_id')::uuid then
      raise exception 'Order % is for another customer', o.order_no;
    end if;
    -- a new delivery needs an open order; an invoice already on the order can still be edited
    if o.status <> 'OPEN' and not exists (select 1 from public.sales where id = v_id and order_id = v_order) then
      raise exception 'Order % is %; reopen it to deliver more', o.order_no, lower(o.status);
    end if;
    v_po := coalesce(o.po_number, v_po);
    v_po_date := coalesce(o.po_date, v_po_date);
  end if;

  if v_id is not null then
    perform public.unpost_sale(v_id);
    delete from public.sale_lines where sale_id = v_id;
    select sale_no into v_no from public.sales where id = v_id;
  else
    v_id := gen_random_uuid();
  end if;

  insert into public.sales (id, sale_no, sale_date, customer_id, broker_id, warehouse_id, vehicle_no, driver_name, driver_phone,
    reference, notes, transport_charge, labour_charge, discount, commission_amount, received_amount, received_account_id,
    received_method, received_cheque_no, received_cheque_date, order_id, po_number, po_date)
  values (v_id, coalesce(v_no, public.next_doc_no('SAL', v_date)), v_date, (p->>'customer_id')::uuid,
    nullif(p->>'broker_id', '')::uuid, (p->>'warehouse_id')::uuid, p->>'vehicle_no', p->>'driver_name', p->>'driver_phone',
    p->>'reference', p->>'notes', coalesce(nullif(p->>'transport_charge', '')::numeric, 0), coalesce(nullif(p->>'labour_charge', '')::numeric, 0),
    coalesce(nullif(p->>'discount', '')::numeric, 0), coalesce(nullif(p->>'commission_amount', '')::numeric, 0),
    coalesce(nullif(p->>'received_amount', '')::numeric, 0), nullif(p->>'received_account_id', '')::uuid,
    coalesce(nullif(p->>'received_method', ''), 'CASH'), nullif(p->>'received_cheque_no', ''), nullif(p->>'received_cheque_date', '')::date,
    v_order, v_po, v_po_date)
  on conflict (id) do update set
    sale_date = excluded.sale_date, customer_id = excluded.customer_id, broker_id = excluded.broker_id,
    warehouse_id = excluded.warehouse_id, vehicle_no = excluded.vehicle_no, driver_name = excluded.driver_name,
    driver_phone = excluded.driver_phone, reference = excluded.reference, notes = excluded.notes,
    transport_charge = excluded.transport_charge, labour_charge = excluded.labour_charge, discount = excluded.discount,
    commission_amount = excluded.commission_amount, received_amount = excluded.received_amount,
    received_account_id = excluded.received_account_id, received_method = excluded.received_method,
    received_cheque_no = excluded.received_cheque_no, received_cheque_date = excluded.received_cheque_date,
    order_id = excluded.order_id, po_number = excluded.po_number, po_date = excluded.po_date, updated_at = now();

  for l in select * from jsonb_array_elements(p->'lines') loop
    v_i := v_i + 1;
    if coalesce(l->>'rate_unit', 'KG') = 'BAG' and coalesce(nullif(l->>'bags', '')::numeric, 0) <= 0 then
      raise exception 'Line %: enter the number of bags for a per-bag rate', v_i;
    end if;
    v_amount := public.line_amount(coalesce(l->>'rate_unit', 'KG'), nullif(l->>'rate', '')::numeric,
      nullif(l->>'qty_kg', '')::numeric, nullif(l->>'bags', '')::numeric);
    insert into public.sale_lines (sale_id, line_no, item_id, lot_id, warehouse_id, bags, bag_size_kg, qty_kg, rate, rate_unit, amount)
    values (v_id, v_i, (l->>'item_id')::uuid, nullif(l->>'lot_id', '')::uuid, nullif(l->>'warehouse_id', '')::uuid,
      coalesce(nullif(l->>'bags', '')::numeric, 0), coalesce(nullif(l->>'bag_size_kg', '')::numeric, 0),
      nullif(l->>'qty_kg', '')::numeric, coalesce(nullif(l->>'rate', '')::numeric, 0), coalesce(l->>'rate_unit', 'KG'), v_amount);
    v_goods := v_goods + v_amount;
  end loop;

  update public.sales set
    goods_amount = v_goods,
    total_amount = v_goods - discount + transport_charge + labour_charge
  where id = v_id
  returning * into h;

  if h.received_amount > 0 and h.received_account_id is null then
    raise exception 'Choose the cash or bank account the money was received into';
  end if;
  select coalesce((select sum(bs.amount) from public.bill_settlements bs join public.money_txns m on m.id = bs.money_txn_id
                   where bs.sale_id = v_id and m.linked_sale_id is distinct from v_id), 0)
       + coalesce((select sum(amount) from public.sale_returns where sale_id = v_id), 0)
  into v_other_paid;
  if h.total_amount + 0.005 < v_other_paid + h.received_amount then
    raise exception 'The invoice total (%) is less than what has already been received or returned against it (%)',
      h.total_amount, v_other_paid + h.received_amount;
  end if;

  perform public.post_sale(v_id);
  return v_id;
end;
$$;

------------------------------------------------------------------------------------------
-- 4. Views: invoice dues (picks up the new columns), order lines and orders with delivery progress
------------------------------------------------------------------------------------------
drop view if exists public.v_sale_dues;
create view public.v_sale_dues with (security_invoker = true) as
select
  s.*, p.name as customer_name, p.name_bn as customer_name_bn,
  coalesce(st.settled, 0) + coalesce(rt.returned, 0) as total_paid,
  s.total_amount - coalesce(st.settled, 0) - coalesce(rt.returned, 0) as due_amount,
  current_date - s.sale_date as age_days
from public.sales s
join public.parties p on p.id = s.customer_id
left join (select sale_id, sum(amount) as settled from public.bill_settlements where sale_id is not null group by sale_id) st on st.sale_id = s.id
left join (select sale_id, sum(amount) as returned from public.sale_returns where sale_id is not null group by sale_id) rt on rt.sale_id = s.id;

-- Delivered = sold on the order's invoices less goods returned against them
drop view if exists public.v_sales_orders;
drop view if exists public.v_sales_order_lines;
create view public.v_sales_order_lines with (security_invoker = true) as
with sold as (
  select s.order_id, sl.item_id, sum(sl.qty_kg) as kg, sum(sl.bags) as bags
  from public.sale_lines sl join public.sales s on s.id = sl.sale_id
  where s.order_id is not null
  group by s.order_id, sl.item_id
),
returned as (
  select s.order_id, r.item_id, sum(r.qty_kg) as kg, sum(r.bags) as bags
  from public.sale_returns r join public.sales s on s.id = r.sale_id
  where s.order_id is not null
  group by s.order_id, r.item_id
)
select
  ol.*,
  coalesce(so.kg, 0) - coalesce(rt.kg, 0) as delivered_kg,
  coalesce(so.bags, 0) - coalesce(rt.bags, 0) as delivered_bags,
  greatest(ol.qty_kg - (coalesce(so.kg, 0) - coalesce(rt.kg, 0)), 0) as remaining_kg,
  greatest(ol.bags - (coalesce(so.bags, 0) - coalesce(rt.bags, 0)), 0) as remaining_bags
from public.sales_order_lines ol
left join sold so on so.order_id = ol.order_id and so.item_id = ol.item_id
left join returned rt on rt.order_id = ol.order_id and rt.item_id = ol.item_id;

create view public.v_sales_orders with (security_invoker = true) as
with lines as (
  select order_id, sum(qty_kg) as ordered_kg, sum(bags) as ordered_bags,
    sum(least(delivered_kg, qty_kg)) as delivered_kg, sum(remaining_kg) as remaining_kg
  from public.v_sales_order_lines group by order_id
),
inv as (
  select order_id, count(*) as invoice_count, sum(total_amount) as invoiced_amount, max(sale_date) as last_delivery
  from public.sales where order_id is not null group by order_id
)
select
  o.*, p.name as customer_name, p.name_bn as customer_name_bn, p.phone as customer_phone,
  coalesce(l.ordered_kg, 0) as ordered_kg, coalesce(l.ordered_bags, 0) as ordered_bags,
  coalesce(l.delivered_kg, 0) as delivered_kg, coalesce(l.remaining_kg, 0) as remaining_kg,
  case when coalesce(l.ordered_kg, 0) > 0 then round(100 * coalesce(l.delivered_kg, 0) / l.ordered_kg, 1) else 0 end as delivered_pct,
  coalesce(i.invoice_count, 0) as invoice_count, coalesce(i.invoiced_amount, 0) as invoiced_amount, i.last_delivery,
  case
    when o.status = 'CANCELLED' then 'CANCELLED'
    when coalesce(l.remaining_kg, 0) <= 0.0005 and coalesce(l.ordered_kg, 0) > 0 then 'DELIVERED'
    when o.status = 'CLOSED' then 'CLOSED'
    when coalesce(l.delivered_kg, 0) > 0 then 'PARTIAL'
    else 'PENDING'
  end as progress,
  (o.status = 'OPEN' and o.delivery_date is not null and o.delivery_date < current_date
    and coalesce(l.remaining_kg, 0) > 0.0005) as overdue
from public.sales_orders o
join public.parties p on p.id = o.customer_id
left join lines l on l.order_id = o.id
left join inv i on i.order_id = o.id;

------------------------------------------------------------------------------------------
-- 5. Security, permissions, audit
------------------------------------------------------------------------------------------
alter table public.sales_orders enable row level security;
alter table public.sales_order_lines enable row level security;

drop policy if exists "read sales_orders" on public.sales_orders;
create policy "read sales_orders" on public.sales_orders for select to authenticated using (public.app_role() is not null);
drop policy if exists "read sales_order_lines" on public.sales_order_lines;
create policy "read sales_order_lines" on public.sales_order_lines for select to authenticated using (public.app_role() is not null);

grant select on public.sales_orders, public.sales_order_lines, public.v_sales_orders, public.v_sales_order_lines,
  public.v_sale_dues to authenticated;

revoke execute on function public.save_sales_order(jsonb), public.set_sales_order_status(uuid, text),
  public.delete_sales_order(uuid), public.save_sale(jsonb) from public, anon;
grant execute on function public.save_sales_order(jsonb), public.set_sales_order_status(uuid, text),
  public.delete_sales_order(uuid), public.save_sale(jsonb) to authenticated;

drop trigger if exists audit_sales_orders on public.sales_orders;
create trigger audit_sales_orders after insert or update or delete on public.sales_orders
for each row execute function public.audit_row();


-- ==== 0016_dashboard.sql ====
-- 0016 Dashboard: more figures for the redesigned dashboard. Same function, the earlier keys are kept.
--   stock      kg and value per item category (paddy -> unsorted -> sorted rice, by-products)
--   sections   per mill section: running batches, batches finished in the period, kg in/out, yield, cost per kg
--   gross_profit, sales_kg, received, paid   for the period
--   cheques    pending cheques in and out, and those due within a week
--   trend      6 months of sales, purchases and gross profit
--   recent     the latest documents of every kind

create or replace function public.dashboard_stats(p_from date, p_to date)
returns jsonb language sql stable as $$
  select jsonb_build_object(
    'cash', (select coalesce(sum(l.debit - l.credit), 0) from public.journal_lines l join public.accounts a on a.id = l.account_id where a.subtype = 'CASH'),
    'bank', (select coalesce(sum(l.debit - l.credit), 0) from public.journal_lines l join public.accounts a on a.id = l.account_id where a.subtype = 'BANK'),
    'receivable', (select coalesce(sum(balance), 0) from public.v_party_balances where balance > 0),
    'payable', (select coalesce(-sum(balance), 0) from public.v_party_balances where balance < 0),
    'stock_value', (select coalesce(sum(remaining_kg * unit_cost), 0) from public.lots where remaining_kg > 0),
    'paddy_kg', (select coalesce(sum(l.remaining_kg), 0) from public.lots l join public.items i on i.id = l.item_id where i.category = 'PADDY'),
    'unsorted_kg', (select coalesce(sum(l.remaining_kg), 0) from public.lots l join public.items i on i.id = l.item_id where i.category = 'UNSORTED'),
    'rice_kg', (select coalesce(sum(l.remaining_kg), 0) from public.lots l join public.items i on i.id = l.item_id where i.category = 'RICE'),
    'byproduct_kg', (select coalesce(sum(l.remaining_kg), 0) from public.lots l join public.items i on i.id = l.item_id where i.category = 'BYPRODUCT'),
    'open_batches', (select count(*) from public.production_batches where status = 'RUNNING'),
    'sales', (select coalesce(sum(total_amount), 0) from public.sales where sale_date between p_from and p_to),
    'sales_count', (select count(*) from public.sales where sale_date between p_from and p_to),
    'sales_kg', (select coalesce(sum(sl.qty_kg), 0) from public.sale_lines sl join public.sales s on s.id = sl.sale_id where s.sale_date between p_from and p_to),
    'gross_profit', (select coalesce(sum(goods_amount - discount - cost_amount), 0) from public.sales where sale_date between p_from and p_to),
    'purchases', (select coalesce(sum(total_cost), 0) from public.purchases where purchase_date between p_from and p_to),
    'purchases_count', (select count(*) from public.purchases where purchase_date between p_from and p_to),
    'expenses', (select coalesce(sum(amount), 0) from public.money_txns where txn_type = 'EXPENSE' and txn_date between p_from and p_to and coalesce(cheque_status, '') <> 'BOUNCED'),
    'received', (select coalesce(sum(amount), 0) from public.money_txns where txn_type = 'RECEIPT' and txn_date between p_from and p_to and coalesce(cheque_status, '') <> 'BOUNCED'),
    'paid', (select coalesce(sum(amount), 0) from public.money_txns where txn_type = 'PAYMENT' and txn_date between p_from and p_to and coalesce(cheque_status, '') <> 'BOUNCED'),
    'profit', (select coalesce(sum(case when type = 'INCOME' then amount else -amount end), 0) from public.report_profit_loss(p_from, p_to)),
    'pending_cheques', (select count(*) from public.money_txns where cheque_status = 'PENDING'),
    'cheques', (
      select jsonb_build_object(
        'in_count', count(*) filter (where txn_type in ('RECEIPT', 'INCOME', 'CAPITAL_IN', 'LOAN_TAKEN', 'LOAN_RECOVER')),
        'in_amount', coalesce(sum(amount) filter (where txn_type in ('RECEIPT', 'INCOME', 'CAPITAL_IN', 'LOAN_TAKEN', 'LOAN_RECOVER')), 0),
        'out_count', count(*) filter (where txn_type not in ('RECEIPT', 'INCOME', 'CAPITAL_IN', 'LOAN_TAKEN', 'LOAN_RECOVER')),
        'out_amount', coalesce(sum(amount) filter (where txn_type not in ('RECEIPT', 'INCOME', 'CAPITAL_IN', 'LOAN_TAKEN', 'LOAN_RECOVER')), 0),
        'due_week', count(*) filter (where coalesce(cheque_date, txn_date) <= current_date + 7),
        'overdue', count(*) filter (where coalesce(cheque_date, txn_date) < current_date)
      )
      from public.money_txns where cheque_status = 'PENDING'
    ),
    'stock', (
      select coalesce(jsonb_agg(jsonb_build_object('category', c.category, 'kg', coalesce(x.kg, 0), 'value', coalesce(x.value, 0)) order by c.ord), '[]'::jsonb)
      from (values ('PADDY', 1), ('UNSORTED', 2), ('RICE', 3), ('BYPRODUCT', 4)) c(category, ord)
      left join (
        select i.category, sum(l.remaining_kg) as kg, sum(l.remaining_kg * l.unit_cost) as value
        from public.lots l join public.items i on i.id = l.item_id where l.remaining_kg > 0 group by i.category
      ) x on x.category = c.category
    ),
    'sections', (
      select coalesce(jsonb_object_agg(x.kind, to_jsonb(x) - 'kind'), '{}'::jsonb)
      from (
        select k.kind,
          (select count(*) from public.production_batches b where b.kind = k.kind and b.status = 'RUNNING') as running,
          (select coalesce(sum(b.input_kg), 0) from public.production_batches b where b.kind = k.kind and b.status = 'RUNNING') as running_kg,
          count(v.id) as completed,
          coalesce(sum(v.input_kg), 0) as material_kg,
          coalesce(sum(v.main_kg), 0) as main_kg,
          coalesce(sum(v.byproduct_kg), 0) as byproduct_kg,
          case when sum(v.input_kg) > 0 then round(100 * sum(v.main_kg) / sum(v.input_kg), 1) end as yield_pct,
          case when sum(v.main_kg) > 0 then round(sum(v.main_cost) / sum(v.main_kg), 2) end as cost_per_kg
        from (values ('DRYER'), ('SORTER')) k(kind)
        left join public.v_production_batches v on v.kind = k.kind and v.status = 'COMPLETED'
          and v.completed_date between p_from and p_to
        group by k.kind
      ) x
    ),
    'trend', (
      select coalesce(jsonb_agg(jsonb_build_object('month', to_char(m, 'YYYY-MM'), 'sales', s, 'purchases', pu, 'gross_profit', gp) order by m), '[]'::jsonb)
      from (
        select m,
          (select coalesce(sum(total_amount), 0) from public.sales where date_trunc('month', sale_date) = m) as s,
          (select coalesce(sum(total_cost), 0) from public.purchases where date_trunc('month', purchase_date) = m) as pu,
          (select coalesce(sum(goods_amount - discount - cost_amount), 0) from public.sales where date_trunc('month', sale_date) = m) as gp
        from generate_series(date_trunc('month', p_to::timestamp) - interval '5 months', date_trunc('month', p_to::timestamp), interval '1 month') m
      ) x
    ),
    'recent', (
      select coalesce(jsonb_agg(r order by r.created_at desc), '[]'::jsonb)
      from (
        select * from (
          select 'SALE' as kind, s.id, s.sale_no as doc_no, s.sale_date as doc_date, p.name as party, s.total_amount as amount, s.created_at
          from public.sales s join public.parties p on p.id = s.customer_id order by s.created_at desc limit 8
        ) a
        union all
        select * from (
          select 'PURCHASE', pu.id, pu.purchase_no, pu.purchase_date, p.name, pu.total_cost, pu.created_at
          from public.purchases pu join public.parties p on p.id = pu.supplier_id order by pu.created_at desc limit 8
        ) b
        union all
        select * from (
          select 'MONEY:' || m.txn_type, m.id, m.txn_no, m.txn_date, p.name, m.amount, m.created_at
          from public.money_txns m left join public.parties p on p.id = m.party_id
          where m.linked_sale_id is null and m.linked_purchase_id is null
          order by m.created_at desc limit 8
        ) c
        union all
        select * from (
          select 'BATCH:' || b.kind, b.id, b.batch_no, b.start_date, null::text, b.input_kg, b.created_at
          from public.production_batches b order by b.created_at desc limit 8
        ) d
        union all
        select * from (
          select 'ORDER', o.id, o.order_no, o.order_date, p.name, o.goods_amount, o.created_at
          from public.sales_orders o join public.parties p on p.id = o.customer_id order by o.created_at desc limit 8
        ) e
        order by created_at desc
        limit 10
      ) r
    )
  )
$$;
